(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c22"]=[{"id":"00003831","register_sub_id":"101","register_pk":"104821","name":"カフェ・パリー","kana":"かふぇ・ぱりー","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1036-1","lat":35.99420992,"lng":139.0835754,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積60㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0068","desc":"木造２階建で，通り側壁面を高く立上げ，片流れの鉄板葺屋根を架け，小屋裏窓を設けて正面３階建にみせる。モルタル塗の外壁は，上部にコーニスを廻し，窓上には装飾をつける。外観を洋風とした店舗兼用住宅で，昭和初期における多様な建築意匠の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003831"},{"id":"00000813","register_sub_id":"101","register_pk":"101803","name":"川越商工会議所（旧武州銀行川越支店）","kana":"かわごえしょうこうかいぎしょ（きゅうぶしゅうぎんこうかわごえしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市仲町1-12","lat":35.92102812,"lng":139.48343037,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上２階建，建築面積566㎡","structure_material":"鉄筋コンクリート造地下１階地上２階建","registered":"1998.10.09(平成10.10.09)","register_no":"11 － 0007","desc":"蔵造りの町並の続く市街地に立地する。外観はドーリス式の列柱を配した重厚な構えになるが，全体の意匠はルネッサンス・リバイバル様式とする。交差点側にバロック風の装飾を付けた特徴的な出入口を設けるなど，時代の特徴を伝える銀行建築の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000813"},{"id":"00010748","register_sub_id":"101","register_pk":"201583","name":"木下半助商店石蔵","kana":"きのしたはんすけしょうてんいしくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市中町4675","lat":35.893339,"lng":139.786305,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"11 ‐ 0146","desc":"店舗及び土蔵の南隣に南北棟で建つ。主構造は木造二階建で、外壁に房州石を張り、石目を意匠的に表して石造風に見せる。上下階とも一室で、通路に面する東面に戸口または窓を二箇所ずつ開き、掛子塗戸形状の鉄扉を吊る。防火性向上への工夫がみられる商品蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010748"},{"id":"00010750","register_sub_id":"101","register_pk":"201585","name":"木下半助商店稲荷社","kana":"きのしたはんすけしょうてんいなりしゃ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県越谷市中町4675","lat":35.893075,"lng":139.785948,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.6㎡、覆屋付","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"11 ‐ 0148","desc":"敷地最奥に東面する、ケヤキ造の一間社流造社殿で、身舎の三方に縁を廻らし、組物出組、腰組四手先とする手の込んだ形式になる。身舎正面の小脇板や庇虹梁上に龍彫刻を配し、組物間に花鳥の彫刻を配して巻斗を置く。随所を技巧的で表情豊かな彫刻で飾る屋敷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010750"},{"id":"00010749","register_sub_id":"101","register_pk":"201584","name":"木下半助商店主屋","kana":"きのしたはんすけしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県越谷市中町4675","lat":35.893157,"lng":139.786051,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積48㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"11 ‐ 0147","desc":"敷地奥寄りに建つ、離れ座敷のような趣の住宅。木造二階建、寄棟造桟瓦葺で、二階窓に庇を廻らせる。上下階とも二室で縁を設けて丸太桁を通す。床廻りや室境の透彫欄間に和洋の銘木を使い、付書院の欄間は巧緻な組子細工を飾る。瀟洒な意匠になる住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010749"},{"id":"00010747","register_sub_id":"101","register_pk":"201582","name":"木下半助商店店舗及び土蔵","kana":"きのしたはんすけしょうてんてんぽおよびどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市中町4675","lat":35.893437,"lng":139.786383,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建及び土蔵造2階建、鉄板葺及び銅板葺、建築面積71㎡","structure_material":"木造平屋建及び土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"11 ‐ 0145","desc":"日光街道越谷宿の中ほどに位置し北面する道具店で、短冊形敷地の前面に店舗及び土蔵を構える。店舗部は低床のミセの東側に土間を通し、正面に摺揚戸を残す。背後に接続する土蔵は二階建で外壁を銅板張とする。明治期の越谷における商店の面影をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010747"},{"id":"00003820","register_sub_id":"101","register_pk":"104810","name":"旧新井商店商品倉庫","kana":"きゅうあらいしょうてんしょうひんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県秩父市本町1400","lat":35.99678446,"lng":139.08245854,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0057","desc":"店舗と主屋の間の中庭南にある。東西棟の切妻造，妻入，桟瓦葺，２階建で，外壁は漆喰塗とする。軒は二重に鉢巻きを廻す。東面１階は旧事務室と接続し，開口部を鳥居形に縁取り，黒漆喰塗の重厚な観音扉をつける。全体に丁寧なつくりの土蔵建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003820"},{"id":"00005076","register_sub_id":"101","register_pk":"106066","name":"旧新井商店店舗及び主屋","kana":"きゅうあらいしょうてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県秩父市本町1400","lat":35.99675416,"lng":139.08254239,"geo_status":"db","era":"明治初期／明治中期移築／大正初期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階一部平屋建、瓦葺、建築面積189㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0056","desc":"店舗は切妻造，平入，２階建で旧秩父往還に東面して建ち，南妻面に平屋建の旧事務室を張り出す。寄棟造，平屋建の主屋は後方に廊下で接続する。店舗は重厚な土蔵造で，正面両端に袖卯建をあげ，２階窓に格子を入れる。明治中期商家の佇まいをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005076"},{"id":"00006675","register_sub_id":"101","register_pk":"107658","name":"旧荒井八郎商店大広間棟","kana":"きゅうあらいはちろうしょうてんおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市佐間1-2351-1","lat":36.13400935,"lng":139.46121509,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"11 － 0111","desc":"事務所兼主屋の西北、洋館との間に建つ。東西棟で西側を寄棟造、東側を切妻とする木造平屋建の桟瓦葺。庭園を望む南側に１０畳２室、その控えとして北側に４畳２室を配し、四周に縁を廻す。トコに欅の一枚板、落掛に黒柿を使うなど贅をつくした内装である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006675"},{"id":"00006674","register_sub_id":"101","register_pk":"107657","name":"旧荒井八郎商店事務所兼主屋","kana":"きゅうあらいはちろうしょうてんじむしょけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市佐間1-2351-1","lat":36.13400142,"lng":139.461388,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積213㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"11 － 0110","desc":"事務所兼主屋と大広間棟、洋館の３棟が雁行型に並ぶ。事務所兼主屋は南面して建つ木造２階建で、寄棟造とし、建築面積２１３㎡に及ぶ。屋根に緑釉瓦を葺き、２階をモルタルで仕上げ、１階にスクラッチタイルを貼り、外観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006674"},{"id":"00006676","register_sub_id":"101","register_pk":"107659","name":"旧荒井八郎商店洋館","kana":"きゅうあらいはちろうしょうてんようかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市佐間1-2351-1","lat":36.13400621,"lng":139.46108985,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造3階建、瓦葺、建築面積46㎡","structure_material":"木造3階建","registered":"2007.12.05(平成19.12.05)","register_no":"11 － 0112","desc":"大広間棟の北西に位置し、大広間棟から廊下で繋がる。木造３階建の洋館で、もとはゲストハウス。屋根を緑釉瓦で葺き、外壁はモルタル仕上げ。欠円形の飾り庇のタイル貼を３連格子窓の上に設けるなど、アクセントを付ける。３階は四方に窓を開く望楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006676"},{"id":"00005257","register_sub_id":"101","register_pk":"106245","name":"旧大月旅館別館","kana":"きゅうおおつきりょかんべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県秩父市番場町1035-3","lat":35.99570021,"lng":139.08386596,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、金属板葺、建築面積46㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"11 － 0095","desc":"木造２階建で，外壁を高く立ち上げた，いわゆる看板建築の外観。角は隅切の形状で，１階入口は竹をモチーフにしたと思われる柱型を設け，コーニスの下はリボンを模した帯風の飾りで装飾する。番場町通と昭和通が交差した角地にあり，際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005257"},{"id":"00004208","register_sub_id":"101","register_pk":"105198","name":"旧小川忠次郎商店店舗及び主屋","kana":"きゅうおがわちゅうじろうしょうてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市忍1-4-6","lat":36.14171369,"lng":139.45687972,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積88㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"11 － 0081","desc":"街路に東面して南北棟の店舗が建ち，その西奥に東西棟の主屋を続ける。店舗南側を土間のミセとし，北側に帳場，ナカノマ，オクを並べ，主屋２階に奥座敷を設ける。北面と西面を塗込めた防火的なつくりが特徴で，行田における足袋産業の隆盛期を物語る建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004208"},{"id":"00002891","register_sub_id":"101","register_pk":"103881","name":"旧柿原商店石塀","kana":"きゅうかきはらしょうてんいしべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.99706991,"lng":139.08255097,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造、延長30m","structure_material":"石造","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0045","desc":"市街地の角地に屋敷を構える銘仙問屋で，敷地北辺を画するのが石塀である。凝灰岩系の切石布積で，延長約３０ｍの規模を有し，傾斜を基礎の玉石積で処理している。中途の通用口はアーチ式開口部とする。昭和初期の商家建築の外構をよく整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002891"},{"id":"00002887","register_sub_id":"101","register_pk":"103877","name":"旧柿原商店店舗及び主屋","kana":"きゅうかきはらしょうてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.997032,"lng":139.082474,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階及び平屋建、瓦葺、建築面積601㎡","structure_material":"木造2階及び平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0041","desc":"木造・２階建（背面一部平屋建）で，寄棟造・桟瓦葺，正面の東面には下屋庇をつける。軒は出桁造で，開口部には繊細な格子戸を入れ，欅材を多用した丁寧なつくりになる。昭和初期の商家建築の形式をよく伝え，市街地の角地でランドマークになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002887"},{"id":"00002888","register_sub_id":"101","register_pk":"103878","name":"旧柿原商店土蔵Ａ","kana":"きゅうかきはらしょうてんどぞうえー","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.996906,"lng":139.08255,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0042","desc":"秩父市街の中心部にある銘仙問屋の倉庫建築で，主屋の背後，敷地西側に建つ。桁行３間半梁間２間の２階建の土蔵で，切妻造・桟瓦葺，平入になる。軒は鉢巻のみと簡素だが，腰の簓子下見板張や基礎の玉石積及び小屋のトラス組など，要所を丁寧なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002888"},{"id":"00002890","register_sub_id":"101","register_pk":"103880","name":"旧柿原商店土蔵Ｃ","kana":"きゅうかきはらしょうてんどぞうしー","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.996967,"lng":139.082321,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0044","desc":"秩父市街の中心部にある銘仙問屋の倉庫建築で，主屋の南西，土蔵Ｂの東側に直交して建つ。桁行５間梁間２間半の２階建，切妻造・桟瓦葺，平入である。１階の戸口や各階の窓の観音扉は丁寧なつくりで，内部には物置の棚も残り，保存状態が良好な土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002890"},{"id":"00002889","register_sub_id":"101","register_pk":"103879","name":"旧柿原商店土蔵Ｂ","kana":"きゅうかきはらしょうてんどぞうびー","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.996971,"lng":139.082382,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0043","desc":"秩父市街の中心部にある銘仙問屋の倉庫建築で，主屋の背後，敷地西側に土蔵Ａと並んで建つ。桁行５間梁間２間の２階建，切妻造・桟瓦葺で，平入とする。１階の戸口や各階の窓の観音扉，腰の簓子下見板張や基礎の玉石積など，丁寧なつくりの土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002889"},{"id":"00000188","register_sub_id":"101","register_pk":"101178","name":"旧本庄商業銀行煉瓦倉庫","kana":"きゅうほんじょうしょうぎょうぎんこうれんがそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県本庄市銀座1-5-16","lat":36.24053447,"lng":139.18336488,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"煉瓦造2階建，瓦葺，建築面積279㎡","structure_material":"煉瓦造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"11 － 0002","desc":"約31m×8.5mの内法の長方形平面の煉瓦造倉庫である。当時高価であった繭や生糸を担保として貯蔵するため、左右対称の位置に設けられた窓に、網戸と鉄扉を設け、通風と防火に配慮している。現在では菓子店の店舗兼工場として活用され、広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000188"},{"id":"00003833","register_sub_id":"101","register_pk":"104823","name":"小池煙草店","kana":"こいけたばこてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1037-7","lat":35.99427988,"lng":139.08385464,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、鉄板葺、建築面積61㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0070","desc":"角地に建つ木造２階建で，通り側の壁を高く立上げ，背面側に鉄板葺の片流れ屋根を架ける。通り側は隅を丸めて連続した壁面とし，コーニス・モールディング・窓周りの縁取りなどと，その他の壁面を色や仕上げで分ける。装飾性に富んだ昭和初期の店舗兼用住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003833"},{"id":"00003843","register_sub_id":"101","register_pk":"104833","name":"小林家住宅主屋","kana":"こばやしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県桶川市寿1-14-11","lat":36.00127,"lng":139.565094,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0080","desc":"中山道桶川宿にある。もと旅籠の建物を，材木商が幕末より店舗に用いてきた。切妻造，桟瓦葺，平入の２階建で，正面に下屋庇を設ける。２階の軒は出桁造で，２階開口部は横一杯に繊細な格子を建て込む。街路に面して建ち，かつての宿場の面影を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003843"},{"id":"00001364","register_sub_id":"101","register_pk":"102354","name":"佐久間旅館奥の間","kana":"さくまりょかんおくのま","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県川越市松江町2-5","lat":35.92149714,"lng":139.48480055,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積65㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"11 － 0010","desc":"川越で由緒ある旅館のひとつ。新築された本館の奥に建ち，小屋組の墨書より明治44年の建築で，大工は清水丑太郎。木造２階建，南面の庭側に縁を廻すほかは防火を重視した大壁造とする。２階にある２つの座敷は銘木を用い，洗練された書院造で格調が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001364"},{"id":"00013227","register_sub_id":"101","register_pk":"366216","name":"島村老茶舗店舗兼主屋","kana":"しまむらろうちゃほてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県桶川市寿二丁目1384","lat":36.00081667,"lng":139.56589722,"geo_status":"db","era":"大正15年／平成30年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積99㎡","structure_material":"木造2階一部平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"11 － 0193","desc":"旧桶川宿に位置し、中山道に西面して建つ商家。木造二階建、切妻造桟瓦葺平入の店舗とその背面に続く平屋建の主屋からなる。店鋪二階の接客用に用いた床棚付の部屋等、内部は当初の姿をよく留める。少なくなりつつある旧宿場町の様相を今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013227"},{"id":"00009709","register_sub_id":"101","register_pk":"195538","name":"十一屋北西商店蔵","kana":"じゅういちやきたにししょうてんくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川口市鳩ヶ谷本町1-1773-1","lat":35.83279589,"lng":139.73983906,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"11 － 0134","desc":"店舗の南隣に東西棟で建つ。土蔵造二階建、桁行一二・七メートル梁間五・四メートル、切妻造桟瓦葺で、東妻面を戸口として下屋を設ける。外壁はモルタル洗出し仕上げで石造風に目地を切り、鉢巻を廻らす。内部は広い一室で、小屋はキングポストトラスとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009709"},{"id":"00009708","register_sub_id":"101","register_pk":"195537","name":"十一屋北西商店店舗","kana":"じゅういちやきたにししょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川口市鳩ヶ谷本町1-1773","lat":35.83287204,"lng":139.73989141,"geo_status":"db","era":"昭和5頃／昭和30頃改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"11 － 0133","desc":"旧鳩ヶ谷宿の県道沿いに東面し、木造二階建、切妻造桟瓦葺で正面を下屋とする。一階正面に成二尺超のケヤキの差物を渡し、二階は繊細な格子をたて、軒は上下階とも出桁造とする。内部もケヤキの良材を多用し、二階は座敷を配する。宿場の面影を伝える商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009708"},{"id":"00006446","register_sub_id":"101","register_pk":"107429","name":"十万石ふくさや行田本店店舗","kana":"じゅうまんごくふくさやぎょうだほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県行田市行田20-15","lat":36.141319,"lng":139.461014,"geo_status":"db","era":"明治16／昭和44曳家","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積96㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"11 － 0108","desc":"旧日光館林道に南面して建つ。間口７．９ｍ、奥行１３ｍ、桟瓦葺の土蔵造２階建で、街路に面する切妻棟の背面にＴ字形に棟が接続する。たちが高く、外観を漆喰で塗り込め、大ぶりの鬼板を棟に戴くなど、重厚な意匠で、街路の歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006446"},{"id":"00004334","register_sub_id":"101","register_pk":"105324","name":"太陽軒","kana":"たいようけん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市元町1-1-23","lat":35.92408938,"lng":139.48476796,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、スレート葺、建築面積154㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"11 － 0085","desc":"関東大震災後の復興商業建築の雰囲気をよく伝える。寄棟造，スレート葺の木造２階建で，軒をやや深く突出させて屋根を隠したつくりとする。隅切りの玄関，玄関上部の円形庇，２階の尖頭隅窓，独特の柱頭を持つ隅柱など，東南角部の表現主義的造形意匠に特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004334"},{"id":"00002603","register_sub_id":"101","register_pk":"103593","name":"武村旅館","kana":"たけむらりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県桶川市南1-8-8","lat":35.99913,"lng":139.567047,"geo_status":"db","era":"江戸末期／明治末期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"11 － 0039","desc":"中山道の桶川宿にあり，街道に北面して建つ。基本は切妻造・平入であるが，明治末期の改造で正面左半分を突出させ，寄棟造の屋根を付ける。柱や差物が木太くしっかりしたつくりで，正面の入口大戸構や縦格子，庇など，宿場の面影を伝える旅籠建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002603"},{"id":"00003828","register_sub_id":"101","register_pk":"104818","name":"秩父銘仙出張所一","kana":"ちちぶめいせんしゅっちょうしょいち","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1001","lat":35.99608274,"lng":139.08306496,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0065","desc":"かつて秩父銘仙で賑わった買継ぎ通りと呼ばれる通りに東面して建つ。木造２階建，切妻造の桟瓦葺，平入で，正面２階軒を出桁造とし，１階には庇をつける。２戸１棟形式で，外観は基本的に中央で左右対称になる。当時の商業地区の景観の一端を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003828"},{"id":"00003830","register_sub_id":"101","register_pk":"104820","name":"秩父銘仙出張所三","kana":"ちちぶめいせんしゅっちょうしょさん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1001","lat":35.99627848,"lng":139.08312239,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0067","desc":"かつて秩父銘仙で賑わった買継ぎ通りに，東面して建つ。木造２階建，切妻造の平入で，正面２階軒を出桁造，１階は下屋を設ける。２戸１棟形式で，正面は２階が真壁造，１階がガラス戸を入れた開放的な店構えで，当時の商業地区の景観の一端を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003830"},{"id":"00003829","register_sub_id":"101","register_pk":"104819","name":"秩父銘仙出張所二","kana":"ちちぶめいせんしゅっちょうしょに","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1001","lat":35.99638035,"lng":139.08316077,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0066","desc":"かつて秩父銘仙で賑わった買継ぎ通りに，東面して建つ。木造２階建，切妻造の平入で，正面２階軒を出桁造，１階は下屋を設ける。正面は真壁造で軽快な壁面構成をみせ，外観は左右対称の２戸１棟形式になり，当時の商業地区の景観の一端を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003829"},{"id":"00001363","register_sub_id":"101","register_pk":"102353","name":"手打ちそば百丈（旧湯宮釣具店）","kana":"てうちそばひゃくじょう（きゅうゆみやつりぐてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市元町1-1-15","lat":35.92461686,"lng":139.48517667,"geo_status":"db","era":"昭和初期（昭和9以前）","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積55㎡","structure_material":"木造3階建","registered":"1999.10.14(平成11.10.14)","register_no":"11 － 0009","desc":"木造３階建て店舗併用住宅で，昭和初期建設の看板建築である。銅板貼りの壁面は破目地で，隅部を柱型風とし，各階の境に軒蛇腹を廻す。２階正面のエジプト風半円付柱，それぞれ意匠を変えたペジメント風の庇など，多彩な様式細部を巧みにまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001363"},{"id":"00012496","register_sub_id":"101","register_pk":"367791","name":"東京ゴルフ倶楽部クラブハウス","kana":"とうきょうごるふくらぶくらぶはうす","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"埼玉県","address":"埼玉県狭山市柏原字通り窪1957-5","lat":35.881481,"lng":139.401627,"geo_status":"geocoded","era":"昭和38年／昭和47年増築、平成6年改修","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造及び木造2階建、銅板葺、建築面積1498㎡","structure_material":"鉄筋コンクリート造及び木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"11 － 0173","desc":"入間川北岸の段丘上にあるゴルフ場の中心部に建つ。一階鉄筋コンクリート造、二階木造で、変形のロの字平面に緩勾配屋根を輻輳してかけ渡す。丸太の柱や梁を多用し、中央に暖炉を備えた山小屋風のラウンジなど、レーモンドの作風が顕著に表れた円熟期の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012496"},{"id":"00006673","register_sub_id":"101","register_pk":"107656","name":"東玉大正館（旧中井銀行岩槻支店）","kana":"とうぎょくたいしょうかん（きゅうなかいぎんこういわつきしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県さいたま市岩槻区本町3-2439-9","lat":35.9490563,"lng":139.69611419,"geo_status":"db","era":"大正後期／平成18改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造2階建、瓦葺、建築面積130㎡","structure_material":"煉瓦造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"11 － 0109","desc":"通りの北側に建つ煉瓦造２階建で、寄棟造桟瓦葺屋根とする。正面を３分割し、上部を半円アーチ型で飾る入口を中央に開き、２階は左右の対称位置に上げ下げ窓を開ける。腰壁を石貼とし、その上を煉瓦タイルとモルタルで仕上げる。大正期の地方銀行の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006673"},{"id":"00015140","register_sub_id":"101","register_pk":"530564","name":"常盤園茶舗倉庫","kana":"ときわえんちゃほそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県深谷市仲町145","lat":36.19475,"lng":139.28306389,"geo_status":"db","era":"明治40年頃／昭和6年頃・令和4年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造及び木造2階建、瓦葺、建築面積36㎡","structure_material":"煉瓦造及び木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"11 - 0230","desc":"旧中山道の南に敷地を構える茶商の商品兼家財用の倉庫。二階建切妻造桟瓦葺で、一階は煉瓦一枚半積で内法高まで立上げ、上部は土台を据えて木造とし、壁面を煉瓦半枚積とする混構造。昭和6年西埼玉地震後と伝わる鉄骨補強した外観が深谷の歴史を伝える倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015140"},{"id":"00011070","register_sub_id":"101","register_pk":"205177","name":"長谷川家住宅旧店蔵及び主屋","kana":"はせがわけじゅうたくきゅうみせぐらおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市岩槻区本町三丁目2839-1他","lat":35.951236,"lng":139.696367,"geo_status":"db","era":"明治前期／昭和56頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"旧店蔵 土蔵造2階建、瓦葺、建築面積49㎡ 主屋 木造平屋建、瓦葺、建築面積53㎡","structure_material":"旧店蔵 土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"11 - 0155","desc":"岩槻旧城下の町人地に位置し、通りに南面して土蔵造二階建の店蔵を建て、背面側に木造平屋建の主屋が続く。旧店蔵の正面には摺揚戸を残す。漆喰塗の大壁に、塗込められた出桁造の軒、影盛を施した大振りな鬼瓦など、関東の商家の特徴を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011070"},{"id":"00011071","register_sub_id":"101","register_pk":"205178","name":"長谷川家住宅文庫蔵","kana":"はせがわけじゅうたくぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市岩槻区本町三丁目2839-1他","lat":35.951343,"lng":139.696319,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"11 - 0156","desc":"敷地北西隅に東面して建つ。土蔵造二階建で、正面には下屋を付けて壁を入れ、蔵前とする。二階の正面中央には窓を開き、銅板葺の庇を付ける。外壁は白漆喰を基調としつつ、窓まわりや一階出入口の楣などの要所には黒漆喰を用いて飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011071"},{"id":"00010421","register_sub_id":"101","register_pk":"202565","name":"浜島家住宅土蔵","kana":"はまじまけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県春日部市粕壁2-6084-3","lat":35.98359,"lng":139.752109,"geo_status":"db","era":"明治前期／昭和37改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"11 － 0144","desc":"旧日光街道沿いに建つ、もと米問屋の座敷蔵。外壁を黒漆喰塗とし、桟瓦葺屋根の鬼瓦に影盛を施すなど関東地方の土蔵造の特徴を示す。南面二階窓の庇は起り付の切妻屋根で銅板葺とし、懸魚を吊る。旧粕壁宿の商家の数少ない遺構で、往事の面影を伝える大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010421"},{"id":"00003823","register_sub_id":"101","register_pk":"104813","name":"武甲酒造柳田総本店店舗","kana":"ぶこうしゅぞうやなぎだそうほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県秩父市宮側町4389","lat":36.000343,"lng":139.08432,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、金属板葺、建築面積329㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0060","desc":"秩父往還に東面して建つ。２階建，切妻造，鉄板葺，平入で，正面に桟瓦葺の下屋庇を設ける。１階正面は開放的な構えとし，２階は横長の開口部に繊細な格子戸を建て込む。全体にたちが低く，屋根勾配も緩やかで，市内で数少ない江戸期の佇まいをみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003823"},{"id":"00009585","register_sub_id":"101","register_pk":"194581","name":"藤城家住宅内蔵","kana":"ふじしろけじゅうたくうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県草加市高砂2-48-1","lat":35.82926835,"lng":139.80646254,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"11 － 0131","desc":"店舗背後に南北棟で建ち、桁行四・六メートル梁間三・六メートル、土蔵造二階建、切妻造桟瓦葺である。外壁は黒漆喰塗で軒蛇腹を廻らし、南妻面の上下階に開口部を設ける。二階の窓では丁寧に施工された掛子塗の土戸を吊り、庇を設ける。重厚なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009585"},{"id":"00009586","register_sub_id":"101","register_pk":"194582","name":"藤城家住宅外蔵","kana":"ふじしろけじゅうたくそとぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県草加市高砂2-48-1","lat":35.82925169,"lng":139.80670524,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積40㎡","structure_material":"土蔵造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"11 － 0132","desc":"敷地の東奥に東西棟で建つ。桁行七・三メートル梁間三・六メートル、土蔵造平屋建、切妻造桟瓦葺で、南正面に下屋を設ける。外壁漆喰塗で鉢巻を廻らし、一階正面に戸口を開き、二階に窓を二所穿つ。内部は一室で壁に荷摺木を並べる。屋敷景観を整える旧米蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009586"},{"id":"00009584","register_sub_id":"101","register_pk":"194580","name":"藤城家住宅店舗","kana":"ふじしろけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県草加市高砂2-48-1","lat":35.8292589,"lng":139.80637688,"geo_status":"db","era":"昭和11／平成21移築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"11 － 0130","desc":"日光街道草加宿で、街道に西面して建つ。木造二階建、切妻造桟瓦葺で、正面に下屋を設ける。正面構えは、一階はガラス戸を、二階は格子をたて、軒は太い腕木で桁を持出し、出桁造りとする。建ちが高く風格ある趣を持つ昭和初期の商家で、宿場の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009584"},{"id":"00005258","register_sub_id":"101","register_pk":"106246","name":"松本教室主屋","kana":"まつもときょうしつしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市上町1289-1","lat":35.99176952,"lng":139.07971193,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積152㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"11 － 0096","desc":"切妻造，桟瓦葺，平入の木造２階建で，正面に下屋を設ける。桁行８間の真壁造である。１，２階とも開口部が多く，軒は２階正面を出桁造とする。当初は旅館として建てられたもので，旧秩父街道に西面し，近代秩父の商業の繁栄を物語る町家建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005258"},{"id":"00004947","register_sub_id":"101","register_pk":"105937","name":"武蔵野銀行行田支店店舗","kana":"むさしのぎんこうぎょうだしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市行田4-2","lat":36.14062828,"lng":139.45896497,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積281㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2005.11.10(平成17.11.10)","register_no":"11 － 0091","desc":"忍貯金銀行として建設。鉄筋コンクリート造２階建の銀行建築で，国道に面する側に吹き抜けの営業室を配する。外壁はスクラッチタイル張とし，開口部周りやコーニスには装飾を施した「カストストン」を張る。小川組の設計施工。昭和初期地方銀行建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004947"},{"id":"00003832","register_sub_id":"101","register_pk":"104822","name":"安田屋","kana":"やすだや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1036","lat":35.9941848,"lng":139.08366832,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階一部3階建、鉄板葺、建築面積43㎡","structure_material":"木造2階一部3階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0069","desc":"角地に建つ木造２階建で，正面の東側と両側面の壁を高く立上げ，背面側に鉄板葺の片流れ屋根を架ける。壁面はモルタル塗で，小屋裏窓を設け３階建にみせ，上部にコーニスを廻し，窓上にアカンサスをあしらった装飾をつける。洋風意匠を摂取した店舗兼用住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003832"},{"id":"00000387","register_sub_id":"101","register_pk":"101377","name":"吉田町立歴史民俗資料館（旧武毛銀行本店）","kana":"よしだちょうりつれきしみんぞくしりょうかん（きゅうぶもうぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県秩父市下吉田3871-1","lat":36.04204902,"lng":139.03615475,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造2階建，瓦葺，建築面積148㎡","structure_material":"煉瓦造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"11 － 0005","desc":"秩父から上毛地方の顧客を対象にした銀行の本店社屋として建築されたもの。正面及び側面前面を白タイル貼りとし，寄棟造，瓦葺の屋根をかける。小規模な建物ながら全体的に質も高く，幾何学文様を主体とした意匠は，近代建築への移行を示す好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000387"},{"id":"00004507","register_sub_id":"101","register_pk":"105497","name":"赤荻本店見世蔵","kana":"あかおぎほんてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町122","lat":36.30343617,"lng":139.87439159,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0167","desc":"茶商の店舗で，街路に東面する。間口４間奥行２間半，土蔵造２階建の平入町家。寄棟造，桟瓦葺で，表に瓦葺の下屋が付く。正面１階は北端に戸袋を置き，ガラス障子を建て込む。１階は店舗，２階は８畳２室の座敷。外壁は砂摺仕上で景観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004507"},{"id":"00004508","register_sub_id":"101","register_pk":"105498","name":"秋葉糀味噌醸造見世蔵","kana":"あきばこうじみそじょうぞうみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県結城市大字結城字浦町174-1","lat":36.30295424,"lng":139.87440421,"geo_status":"db","era":"大正13／昭和9改造","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"土蔵造及び木造2階一部平屋建、瓦葺、建築面積108㎡","structure_material":"土蔵造及び木造2階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0168","desc":"味噌醸造業の店舗で，街路に東面する。土蔵造２階建で，南半が切妻造平入，北半が半切妻造妻入で，瓦葺の庇が付く。正面は昭和９年の道路拡幅で改修された。１階南半が土間の店舗，北半が居室，２階は座敷１０畳など４室を配し，背後に平屋の附属屋が続く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004508"},{"id":"00001238","register_sub_id":"101","register_pk":"102228","name":"荒川家住宅石蔵","kana":"あらかわけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県筑西市甲868","lat":36.31138169,"lng":139.98083034,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造２階建，瓦葺，建築面積83㎡","structure_material":"石造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0011","desc":"敷地の東北端に位置する東西棟、桟瓦葺、切妻屋根の２階建石蔵。桁行５間、梁間２間半の規模で、栃木近辺でよく見かける大谷石による石蔵に似た造りになるが、東妻面の開口部は直線構成の額縁をとり、雨除けの庇と持送りを付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001238"},{"id":"00008634","register_sub_id":"101","register_pk":"149355","name":"荒川家住宅旧店蔵","kana":"あらかわけじゅうたくきゅうみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県筑西市字田町甲929-1他","lat":36.31097141,"lng":139.9809019,"geo_status":"db","era":"明治後期／昭和8年移築・平成元年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0254","desc":"通りに北面して建つ。桁行9.5ｍ梁間6.8ｍ、土蔵造を基本に東妻面に切石積を見せる。たちの高い2階建。切妻造桟瓦葺で、正面に下屋を付ける。2階は黒漆喰仕上げとし、広く開口を穿ち、鉄格子を嵌める。重厚な表構えになる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008634"},{"id":"00008633","register_sub_id":"101","register_pk":"149354","name":"荒川家住宅主屋","kana":"あらかわけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県筑西市字田町甲929-1他","lat":36.31086488,"lng":139.98084033,"geo_status":"db","era":"明治25年／昭和8年移築増築・平成元年・平成17年改修","year":1892,"year_source":"converted","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、銅板葺、建築面積131㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0253","desc":"敷地の中央に位置し、南側は庭園に望む。木造2階建、建築面積131㎡。東寄棟西切妻造の東西棟を主棟とし、東面に落棟で寄棟造を張り出す。銅板葺。1階は中廊下を基本とし、1、2階に座敷を設ける。2階座敷には上質なつくりのトコや付書院等を構える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008633"},{"id":"00008635","register_sub_id":"101","register_pk":"149356","name":"荒川家住宅土蔵","kana":"あらかわけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県筑西市字田町甲929-1他","lat":36.31075313,"lng":139.98084006,"geo_status":"db","era":"明治後期／平成元年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0255","desc":"主屋の南、庭園を挟んだ位置に建つ。東西棟の桁行9.4ｍ梁間5.6ｍ。土蔵造2階建、切妻造桟瓦葺。北面に深い下屋をかけて、出入口2ヶ所を穿ち、掛子塗の両開戸を吊る。内部は和小屋で漆喰仕上げ。重厚な外観が庭園景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008635"},{"id":"00001235","register_sub_id":"101","register_pk":"102225","name":"荒川家住宅店蔵","kana":"あらかわけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県筑西市甲868","lat":36.31118883,"lng":139.98085716,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積99㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0008","desc":"３階建洋館の東に隣接して建つ土蔵造２階建、桟瓦葺、東西棟で平入の店舗。間口５間半、奥行３間で、正面前面に１間分の下屋を差出す。２階正面は左右の戸袋部を除いて開口とし開放性の強いつくりとする。明治期商店街の様子を伝えていることで貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001235"},{"id":"00001998","register_sub_id":"101","register_pk":"102988","name":"伊勢屋旅館主屋","kana":"いせやりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字下宿町193","lat":36.27698159,"lng":140.09952759,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積77㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0048","desc":"伊勢屋は２代前まで「勢州楼」と称する料亭も営んでいた明治以来の老舗旅館。主屋は桁行５間，梁間４間，総２階建で，２階に床の間を備えた３つの客室を設ける。桟瓦葺の屋根は西側が寄棟造，東側が切妻造になり，通りの景観の際だった存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001998"},{"id":"00003368","register_sub_id":"101","register_pk":"104358","name":"市塚紀夫家住宅店舗及び主屋","kana":"いちつかのりおけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁236-1","lat":36.277954,"lng":140.097595,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積235㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0090","desc":"Ｌ字型平面で木造平屋建，屋根は桟瓦葺とする。街路に東面して建つ店舗は寄棟造，平入で，大棟に切妻造の煙出をつけ，正側面に下屋を設ける。住居は店舗西面北端から西に延び，寄棟造屋根をあげる。低平な外観は江戸時代以来の伝統を継承したと思われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003368"},{"id":"00002874","register_sub_id":"101","register_pk":"103864","name":"入江家住宅主屋","kana":"いりえけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁220","lat":36.277889,"lng":140.09938,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"08 － 0068","desc":"町中心部，御陣屋前通りの西側に位置する。桁行６間，梁間３間の規模を有する寄棟造，桟瓦葺，妻入，外装簓子下見板張の木造総２階建で，主屋南側に１間棟門，正面にむくりのついた下屋庇を設ける。２階の軒を高くとり，歴史的街路景観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002874"},{"id":"00001402","register_sub_id":"101","register_pk":"102392","name":"潮田家住宅袖蔵","kana":"うしおだけじゅうたくそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁189","lat":36.277142,"lng":140.09903,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積118㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"08 － 0018","desc":"見世蔵の北側に接して建ち，妻面を通りに向けている。明治４５年の建築で，総２階建・切妻造・桟瓦葺，外壁を簓子下見板張とし，見世蔵１階の帳場に面して観音扉口を設ける。高さや壁面線が見世蔵と一体感を持ち，通りに面した商家の構えとして重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001402"},{"id":"00001401","register_sub_id":"101","register_pk":"102391","name":"潮田家住宅見世蔵","kana":"うしおだけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁189","lat":36.27706042,"lng":140.09899107,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積281㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"08 － 0017","desc":"潮田家は筑波山北に位置する真壁町のほぼ中心にあり，かつては呉服太物商を営んでいた。見世蔵は明治４３年の建築で，１階は通り側に広く帳場を構え，奥に座敷を配する。高い棟積をもつ重厚な黒漆喰塗の町家で，御陣屋前通りの角地に際だった姿をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001401"},{"id":"00003947","register_sub_id":"101","register_pk":"104937","name":"大森家住宅主屋","kana":"おおもりけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町桜井字東169-1","lat":36.28066124,"lng":140.10399222,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"08 － 0120","desc":"製糸業の家の店舗兼住居。表通りに面する２階建，寄棟造，平入の店舗の奥に平屋，寄棟造の住居部分が接続する。内部は１階前面下屋と南半を広い土間とし北半に座敷を並べ，２階は田字型に部屋を取る。階高を押さえた町屋の姿は，地域の景観上欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003947"},{"id":"00003498","register_sub_id":"101","register_pk":"104488","name":"大和田家貸店舗","kana":"おおわだけかしてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-3-24","lat":36.1899038,"lng":140.274887,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積138㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0103","desc":"市街地に位置するいわゆる看板建築。間口５間，奥行１０間半で，正面には柱頭付円柱形を３本配し，中央柱で店舗を２軒に仕切る。左端柱を上部と下部でずらし，軒下に垂木風歯形飾をあしらい，屋根に３本の煙突風の突起物を立ち上げるなど特異な造形をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003498"},{"id":"00005736","register_sub_id":"101","register_pk":"106724","name":"奥順壱の蔵","kana":"おくじゅんいちのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町82","lat":36.303391,"lng":139.877319,"geo_status":"db","era":null,"year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治","structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"08 － 0221","desc":"南北に長い敷地の北端に道路に面して建つ。桁行４間，梁間４間の規模で，木造２階建，切妻造，桟瓦葺とする。側面及び２階軒裏を漆喰で塗り込め，側面腰を下見板張とする。２階に８畳間の座敷を設ける。塗屋形式の店舗が通りの歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005736"},{"id":"00004501","register_sub_id":"101","register_pk":"105491","name":"奥順店舗","kana":"おくじゅんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県結城市大字結城字大町9-2、12-2","lat":36.30356044,"lng":139.87731319,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階一部平屋建、瓦葺、建築面積119㎡","structure_material":"木造2階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0161","desc":"見世蔵の西に並ぶ。街路に面した桁行３間半梁間２間半を２階建とし，１階が店舗，２階が１２畳大の和室となる。屋根は切妻造，桟瓦葺で外壁は銅板張。正面１階はガラス戸，２階は肘掛窓とする。東側面と北背面に平屋を接続して居室を配し，事務所等とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004501"},{"id":"00004500","register_sub_id":"101","register_pk":"105490","name":"奥順見世蔵","kana":"おくじゅんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町9-2","lat":36.303516,"lng":139.877457,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0160","desc":"間口４間奥行２間半，土蔵造２階建の町家。屋根は切妻造，桟瓦葺で表に瓦庇が付く。正面１階は全面に建具を建て込み，２階窓の両端に戸袋を設ける。大工棟梁は水戸の松本惣八。１階は前面庇部と東半を土間とした古風な店構えで，２階に１２畳大の座敷をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004500"},{"id":"00007449","register_sub_id":"101","register_pk":"108431","name":"奥庄店舗兼主屋","kana":"おくしょうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県結城市大字結城字大町24他","lat":36.30390359,"lng":139.87552595,"geo_status":"db","era":"昭和10／昭和18・昭和51改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"08 － 0229","desc":"結城城下の大町通りに南面して建つ。木造２階建、切妻造桟瓦葺の平入町家で、背面直角に２階屋を付設し、正面の棟を店舗、奥を居室とする。出桁造で、１階に小庇を付け、１、２階とも正面にガラス戸をたて開放的に扱う。伝統的な商家の構えをよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007449"},{"id":"00006781","register_sub_id":"101","register_pk":"107763","name":"小倉商店店舗兼主屋","kana":"おぐらしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町116","lat":36.303711,"lng":139.87468145,"geo_status":"db","era":"明治初期／平成7改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"08 － 0227","desc":"街路に西面して建つ木造２階建の平入町家。桁行４間梁間５間で切妻造桟瓦葺とする。正面１階は近年の改修で、２階は１本溝に格子戸を建て込む。内部は南を土間、北を１列３室の床上部とし、２階に８畳２室を設ける。出桁造の軒と妻壁の梁組が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006781"},{"id":"00004110","register_sub_id":"101","register_pk":"105100","name":"亀屋商事（旧飯島家住宅）本館","kana":"かめやしょうじ（きゅういいじまけじゅうたく）ほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県古河市雷電町1-78","lat":36.19765893,"lng":139.712662,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、銅板葺一部亜鉛葺、建築面積200㎡、塔屋付","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0124","desc":"県道東野田古河線沿いに建つ。桁行６間半梁間５間半規模の木造２階建で，柱型のタイル張，縦長窓，パラペット状の軒蛇腹や玄関部の大理石円柱など洋風に仕上げる。西南隅に建ち上げた国会議事堂風の望楼は地区のシンボル的存在となっている。棟梁は谷部貞雄。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004110"},{"id":"00004112","register_sub_id":"101","register_pk":"105102","name":"亀屋商事（旧飯島家住宅）本館旧食堂及び旧浴室","kana":"かめやしょうじ（きゅういいじまけじゅうたく）ほんかんきゅうしょくどうおよびきゅうよくしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県古河市雷電町1-78","lat":36.19780945,"lng":139.71262869,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0126","desc":"主屋から北へ延びる廊下の突き当たりに位置し，東側に桁行３間半梁間３間規模，南北棟，片寄棟造の旧食堂，西側に桁行３間梁間２間規模，東西棟，寄棟造の旧浴室を配する。外装は下見板張で，旧食堂の窓にステインドグラス，旧浴室では傘状の竿縁天井を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004112"},{"id":"00004111","register_sub_id":"101","register_pk":"105101","name":"亀屋商事（旧飯島家住宅）本館土蔵","kana":"かめやしょうじ（きゅういいじまけじゅうたく）ほんかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県古河市雷電町1-78","lat":36.19776825,"lng":139.71259862,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積20㎡","structure_material":"土蔵造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0125","desc":"本館主屋北西隅の玄関部の北方に位置し，東西棟で建つ。桁行２間半梁間２間規模，切妻造，桟瓦葺，妻入の２階建土蔵で，主屋と旧食堂及び旧浴室を結ぶ廊下の西面に戸口を開け，南面２階に窓２箇所を開ける。主屋，旧浴室とともに本館西面を構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004111"},{"id":"00001862","register_sub_id":"101","register_pk":"102852","name":"川島書店見世蔵","kana":"かわしましょてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁335","lat":36.27855886,"lng":140.099976,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0035","desc":"川島家は江戸末期より生薬店を営み，見世蔵は初代清兵衛が建てたと伝える。桁行４間・梁間２間半，正面下屋庇付の切妻造・平入の土蔵造建築。１階を店舗，２階を座敷と板の間の２室とする。真壁町の中で最も整った江戸型の見世蔵で，保存状態も良好である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001862"},{"id":"00003352","register_sub_id":"101","register_pk":"104342","name":"きそば東京庵店舗兼住宅","kana":"きそばとうきょうあんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-3-16","lat":36.18945152,"lng":140.27428472,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積185㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0074","desc":"木造２階建で，東西に細長い敷地形状に合わせて建てられ，桁行約２５ｍの規模を持つ。西側の街路に正面を向けた，入母屋造，妻入で，正面に２階軒庇と下屋庇を設ける。全体に木割の細いつくりとし，軒を吹寄垂木とするなど，軽快な数寄屋風の意匠としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003352"},{"id":"00003783","register_sub_id":"101","register_pk":"104773","name":"北岡家住宅店舗及び主屋","kana":"きたおかけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町飯塚字壱番耕地104","lat":36.27572517,"lng":140.098175,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0119","desc":"南北の通りに東面して建つ。桁行６間梁間４間規模，寄棟造，桟瓦葺，妻入の平屋建町家で，正面に１間幅の下屋庇を差し掛ける。通りに面して店舗を設け，奥に６畳，８畳，床・書院付き８畳をＬ字型に配する。大工は近隣川原町の小原某と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003783"},{"id":"00005733","register_sub_id":"101","register_pk":"106721","name":"キヌヤ薬舗店舗","kana":"きぬややくほてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町9","lat":36.30347338,"lng":139.87757734,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"08 － 0220","desc":"南北に長い敷地の南端に道路に面して建つ。桁行３間半，梁間３間半の規模で，木造２階建，切妻造，桟瓦葺とする。側面及び２階軒裏を漆喰で塗り込める。１階を土間，４畳間，板の間とし，２階の４畳半２室を続き間座敷とする。小規模であるが丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005733"},{"id":"00001865","register_sub_id":"101","register_pk":"102855","name":"木村家住宅（小田部生花店）見世蔵","kana":"きむらけじゅうたく（こたべせいかてん）みせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁字高上町217-1","lat":36.277676,"lng":140.099304,"geo_status":"db","era":"嘉永6以前","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0038","desc":"木村家の見世蔵は天保８年火災後，家相図より嘉永６年までに再建されたことがわかる。御陣屋前通りの西側にあり，桁行５間・梁間２間半，正面下屋庇付の切妻造・平入の土蔵造建築。全体に建物の高さが低く，２階開口部が少ないなど，江戸末期の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001865"},{"id":"00006438","register_sub_id":"101","register_pk":"107421","name":"旧おかめ旅館本館","kana":"きゅうおかめりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県東茨城郡大洗町磯浜町2315-4他","lat":36.32081503,"lng":140.56425912,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積187㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"08 － 0226","desc":"涸沼川に北面して建つ木造２階建の旧旅館。屋根は桟瓦葺で、川に面する東西棟を入母屋造とし、寄棟造を直交して南に造る。正面に庇を設け、１階に出格子を付ける。出桁と木太い半繁垂木が深い軒を造り、重厚な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006438"},{"id":"00003776","register_sub_id":"101","register_pk":"104766","name":"旧小野瀬家住宅店舗","kana":"きゅうおのせけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県龍ケ崎市4252","lat":35.905823,"lng":140.187881,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階一部平屋建、瓦葺一部鉄板葺、建築面積210㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0112","desc":"龍ヶ崎市街上町往還に南面して建つ。桁行５間梁間３間，切妻造，桟瓦葺の平入２階建町家で，前面に幅５尺の下屋を差し掛ける。１階店舗の１尺２寸角大黒柱や，成３尺幅１尺材などを用いて整然と組んだ根太天井，下屋部の海老虹梁など剛直な架構に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003776"},{"id":"00005732","register_sub_id":"101","register_pk":"106720","name":"旧黒川米穀店店舗","kana":"きゅうくろかわべいこくてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字西の宮町1319-2","lat":36.304119,"lng":139.878479,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積93㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"08 － 0219","desc":"敷地の南側道路に面して建つ。桁行７間，梁間４間の規模で，土蔵造２階建，切妻造，桟瓦葺，妻入とする。南半を土間とし，奥に６畳間を設け，２階は１０畳の座敷２室を並べる。一部を落ち棟とし，棟積み及び鬼瓦を大きく造り，重厚な意匠としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005732"},{"id":"00011448","register_sub_id":"101","register_pk":"210417","name":"旧大子銀行本店","kana":"きゅうだいごぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字金町西側642-2","lat":36.771368,"lng":140.355255,"geo_status":"db","era":"大正6年／昭和48年頃改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺一部銅板葺、建築面積202㎡、塔屋付","structure_material":"木造2階一部平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"08-0299","desc":"旧街道沿いの角地に東面して建つ。木造二階建、寄棟造で、背面に平屋建が附属する。内部は金庫室、階段廻りや天井に往時の姿を良く留める。ドーム屋根の塔屋、円柱やペディメントで飾る正面出入口などが特徴的であり、地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011448"},{"id":"00011052","register_sub_id":"101","register_pk":"205159","name":"旧大徳呉服店袖蔵","kana":"きゅうだいとくごふくてんそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県土浦市中央一丁目914-4","lat":36.082483,"lng":140.200035,"geo_status":"db","era":"安政6／平成10改修","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0287","desc":"店蔵北棟の西に前室を介して建つ。商品の呉服を収納していたことから、かつては呉服蔵とも称された。南北両妻面の二階には両開の窓が設けられ、庇を付ける。外壁はもと黒漆喰とみられる。妻面を街路側に見せ、土浦旧城下の景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011052"},{"id":"00011050","register_sub_id":"101","register_pk":"205157","name":"旧大徳呉服店店蔵北棟","kana":"きゅうだいとくごふくてんみせぐらきたとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県土浦市中央一丁目914-4","lat":36.082529,"lng":140.200154,"geo_status":"db","era":"江戸末期／明治18・同44・平成10改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0285","desc":"土浦旧城下の町人地にあたり、旧水戸街道の角地に北面して建つ。土蔵造二階建、平入とする。正面を塗込める漆喰は、もと黒漆喰とみられる。天保大火後の江戸末期に建てられた町家としては二階のせいも高く、発達した姿を見せる。城下の歴史的な景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011050"},{"id":"00011051","register_sub_id":"101","register_pk":"205158","name":"旧大徳呉服店店蔵南棟","kana":"きゅうだいとくごふくてんみせぐらみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目914-4","lat":36.082442,"lng":140.200185,"geo_status":"db","era":"明治初期／平成10改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積134㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0286","desc":"街道に北面して建つ北棟の南に接して建つ。東面は土蔵風に造るが、屋根は寄棟、内部は座敷を主とした建物で、一階には八畳と六畳の続き間座敷、二階にも三室の続き間座敷を設ける。本格的な書院座敷を備えるなど、防火性能と瀟洒な内装を具備した建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011051"},{"id":"00011054","register_sub_id":"101","register_pk":"205161","name":"旧大徳呉服店向蔵","kana":"きゅうだいとくごふくてんむこうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目914-5他","lat":36.082266,"lng":140.200239,"geo_status":"db","era":"明治前期／平成12改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0289","desc":"元蔵の南に東西棟で建つ。北に向けて出入口を開く。もとは布団や食器類などの家財道具を収納していた。小屋は登梁形式とする。東妻側の二階には窓を開いて掛子塗の戸を吊り、腕木で支える庇を付けて、土蔵造の建物が連続する街路の景観に変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011054"},{"id":"00011053","register_sub_id":"101","register_pk":"205160","name":"旧大徳呉服店元蔵","kana":"きゅうだいとくごふくてんもとぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県土浦市中央一丁目914-5他","lat":36.082331,"lng":140.200251,"geo_status":"db","era":"天保13／平成11改修","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0288","desc":"店蔵南棟の南に中庭を介して建つ。南北棟の切妻造二階建で、北正面に庇を設け、二階にも掛子塗の戸を吊る窓を開く。小屋は登梁形式とする。比較的小規模な蔵ではあるが、土浦城下では希少な、天保大火を免れた、年代の明らかな土蔵の遺構として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011053"},{"id":"00010740","register_sub_id":"101","register_pk":"201575","name":"旧田村呉服店蔵","kana":"きゅうたむらごふくてんくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字日向39-1","lat":36.178144,"lng":140.09177,"geo_status":"db","era":"大正期／平成24改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積32㎡、渡屋根付","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0275","desc":"主屋後方、南北に長い敷地の中央寄りに建つ二階建の土蔵。桁行三間梁間二間半、和小屋組の南北棟、切妻造桟瓦葺で、南妻面の観音扉口には下屋庇を設ける。黒漆喰塗の外壁、北妻の押縁下見板覆い、鉢巻付の軒など丁寧な施工の商品蔵で、商家の構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010740"},{"id":"00010741","register_sub_id":"101","register_pk":"201576","name":"旧田村呉服店穀蔵及び浴室","kana":"きゅうたむらごふくてんこくぐらおよびよくしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字日向39-1","lat":36.178205,"lng":140.091897,"geo_status":"db","era":"大正期／昭和前期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造及び木造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造及び木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0276","desc":"桁行三間半の細長い平屋建の土蔵で、敷地中央東側にある。南北棟の切妻造桟瓦葺で、外壁は漆喰塗とし、内部は和小屋組を見せる。西面は扉口、南妻面に庇付の窓を設け、増築された浴室を接続する。商家の後方空間にある簡明な施設で、往時の暮らしぶりを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010741"},{"id":"00010742","register_sub_id":"101","register_pk":"201577","name":"旧田村呉服店炊事場","kana":"きゅうたむらごふくてんすいじば","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字日向39-1","lat":36.178148,"lng":140.091895,"geo_status":"db","era":"大正期／昭和30頃改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0277","desc":"主屋の北東方、蔵の東に位置する。桁行五間弱、梁間一間強の南北に細長い建物で、南よりスイジバ、ヨクシツ、ベンジョの平面になる。木造平屋建、切妻造桟瓦葺、真壁造の荒壁仕上であるが、基礎切石の一部を高く積む。当初から別棟で、生活様態を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010742"},{"id":"00010739","register_sub_id":"101","register_pk":"201574","name":"旧田村呉服店ミセ蔵兼主屋","kana":"きゅうたむらごふくてんみせぐらけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字日向39-1","lat":36.17803,"lng":140.091795,"geo_status":"db","era":"大正期／昭和前期・同後期・平成24頃改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積152㎡、渡屋根付","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0274","desc":"敷地の南で道路に面する。前寄りをミセ蔵、後方を主屋とし、西側二階が当初で、東側二階は昭和前期の増築とみられる。前面一間通りを下屋とし、寄棟造妻入の二階が二棟並んだ正面外観は特異で、黒漆喰塗の重厚な外壁とともに、地域のランドマーク的存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010739"},{"id":"00010908","register_sub_id":"101","register_pk":"208879","name":"旧外池呉服店店舗","kana":"きゅうとのいけごふくてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字金町東側624・625合併","lat":36.771508,"lng":140.355522,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積103㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"08-0281","desc":"大子町の中心部に位置する。通りに西面して建つ二階建の土蔵造店舗で、外壁を黒漆喰で塗込める。一階を店舗、二階を座敷とし、二階正面には四か所の観音開の窓を穿って、掛子塗の窓を吊って高い左官技術を見せる。重厚な外観で街路に歴史的な景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010908"},{"id":"00011056","register_sub_id":"101","register_pk":"205163","name":"旧野村さとう店袖蔵","kana":"きゅうのむらさとうてんそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目950・952合併","lat":36.082689,"lng":140.200072,"geo_status":"db","era":"明治前期／平成14改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0291","desc":"店舗兼主屋の東に接して、旧水戸街道に南面して建つ。南北棟の二階建土蔵で、もとは一階に商品の砂糖を、二階にはその他の物品を収納したと伝わる。土浦旧城下の町家でみられる、店舗と袖蔵を並べて街路側に妻面と平面を見せる構成で、町並みに変化をつけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011056"},{"id":"00011055","register_sub_id":"101","register_pk":"205162","name":"旧野村さとう店店舗兼主屋","kana":"きゅうのむらさとうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目950・952合併","lat":36.08269,"lng":140.199991,"geo_status":"db","era":"明治中期／平成14改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0290","desc":"土浦旧城下の町人地にあたり、旧水戸街道に南面して建つ。店舗兼主屋は総二階建で、店舗部は東西棟、主屋部は南北棟として丁字に組む。正面二階は簓子下見板張とし、軒は出桁造として陰影を付ける。重厚な構えで旧城下の景観を形づくる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011055"},{"id":"00011057","register_sub_id":"101","register_pk":"205164","name":"旧野村さとう店文庫蔵","kana":"きゅうのむらさとうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目950・952合併","lat":36.082811,"lng":140.200044,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0292","desc":"敷地北奥、袖蔵の北方に南北棟で建つ。二階建土蔵で、雛人形などの家財道具などを納めたと伝わる。南に出入口を設け、一階の出入口、二階の窓ともに黒漆喰塗の戸を吊って掛子塗とする外観が特徴。隣接する不動院参道側には漆喰壁を見せ、歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011057"},{"id":"00011058","register_sub_id":"101","register_pk":"205165","name":"旧野村さとう店煉瓦蔵","kana":"きゅうのむらさとうてんれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目950・952合併","lat":36.082852,"lng":140.199965,"geo_status":"db","era":"明治中期／平成14・同24改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造平屋建、瓦葺、建築面積28㎡","structure_material":"煉瓦造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0293","desc":"敷地北奥、店舗兼主屋の北方に南北棟で建つ。煉瓦造の蔵で建ちが高く、現在は平屋建であるが、もとは二階建であったと伝わる。煉瓦はイギリス積とし、開口上部にはアーチを用いる。土蔵造を中心とする町並みの中で、煉瓦造が異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011058"},{"id":"00001869","register_sub_id":"101","register_pk":"102859","name":"旧真壁郵便局","kana":"きゅうまかべゆうびんきょく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁297","lat":36.27818266,"lng":140.09957382,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄網コンクリート造2階建、建築面積83㎡","structure_material":"鉄網コンクリート造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0042","desc":"当初は第五十銀行（現常陽銀行）の真壁支店として建設され，中心街の角地にあり，ランドマークとして親しまれてきた。ほぼ正方形平面の総２階建で，１階右奥に金庫室が突出する。装飾的要素をほとんど用いない平滑な外観は，昭和初期の意匠の流れを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001869"},{"id":"00005235","register_sub_id":"101","register_pk":"106223","name":"栗山呉服店店舗兼住宅","kana":"くりやまごふくてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-4-25","lat":36.18901436,"lng":140.27470077,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、スレート葺、建築面積84㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"08 － 0202","desc":"水戸街道に直交する街路に北面して建つ。間口９．１ｍ，奥行９．４ｍ規模の木造２階建，平入，出桁造の商店建築。正面は広い開口部の両端に戸袋を配した対称的な外観で，妻側は押縁下見板張とする。昭和４年の大火後に形成された市街地の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005235"},{"id":"00001656","register_sub_id":"101","register_pk":"102646","name":"五木宗レンガ蔵","kana":"ごきそうれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県常総市水海道元町3421-1","lat":36.023048,"lng":139.986603,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造3階建、建築面積18㎡","structure_material":"煉瓦造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0028","desc":"鬼怒川左岸に発達した河岸問屋のひとつである五木田宗右衛門家の３階建煉瓦造蔵で、「五木宗レンガ造りの蔵」として親しまれている。腰積、胴蛇腹、開口部廻りなどに焼過煉瓦を使用した丁寧な造りになり、内部を構造補強し資料館等として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001656"},{"id":"00004506","register_sub_id":"101","register_pk":"105496","name":"小西見世蔵","kana":"こにしみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町114","lat":36.30322528,"lng":139.87474648,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積88㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0166","desc":"もと金物店で，南を正面とする。間口６間奥行３間半の土蔵造２階建，平入の町家。切妻屋根を桟瓦葺とし，表に瓦葺庇が付く。外壁は黒漆喰塗で，正面１階に出窓，２階は額縁付の格子窓とした重厚な外観である。１階は事務所と店舗，２階は座敷と物置とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004506"},{"id":"00003379","register_sub_id":"101","register_pk":"104369","name":"小林商店米蔵","kana":"こばやししょうてんこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町飯塚171-2","lat":36.28015034,"lng":140.095459,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0101","desc":"木造平屋建，切妻造，平入，桟瓦葺で，東側正面に幅５尺の下屋をつける。真壁造で，正面腰と側面を簓子下見板張とし，正面中央のみ開口部とする。倉庫建築だが，土蔵造でなく町家風の形式で，北側に並び建つ店舗と，連続性のある街路景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003379"},{"id":"00003378","register_sub_id":"101","register_pk":"104368","name":"小林商店店舗","kana":"こばやししょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町飯塚171-2","lat":36.280228,"lng":140.095413,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0100","desc":"旧下館街道に面して建つ。街路側は木造平屋建，寄棟造，平入，下屋付で，背後に寄棟造，下屋付の座敷部分を延ばす。屋根はすべて桟瓦葺である。帳場とＬ字型土間からなる店構えを含め，伝統的な形式を継承し，ガラス戸や戸袋などに昭和初期の意匠が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003378"},{"id":"00003779","register_sub_id":"101","register_pk":"104769","name":"桜井家住宅店舗","kana":"さくらいけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁409","lat":36.278904,"lng":140.102631,"geo_status":"db","era":"明治初期／大正10頃増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0115","desc":"旧町屋村の中心部に位置し，通りに南面して建つ。桁行５間梁間２間半，切妻造，桟瓦葺の平入町家で，２階は大正中期の増築。１階は東方に土間，西方に帳場を配し，正面は１階腰を石張，２階を簓子下見とし，西妻面のみ土蔵造として火災に備えたつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003779"},{"id":"00003499","register_sub_id":"101","register_pk":"104489","name":"十七屋履物店店舗兼住宅","kana":"じゅうしちやはきものてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-4-22","lat":36.188923,"lng":140.274338,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、スレート葺、建築面積135㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0104","desc":"市繁華街の中町通りに面して建ついわゆる看板建築。間口４間半，奥行１１間半で，正面右側に商品陳列棚を設ける。二階は柱頭風持送上につくった柱型を中心に縦長の連窓を左右に配し，軒下にはロンバルディア帯をあしらう。昭和初期に隆盛した商業建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003499"},{"id":"00004909","register_sub_id":"101","register_pk":"105899","name":"すがや化粧品店店舗兼住宅","kana":"すがやけしょうひんてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-5-1","lat":36.189037,"lng":140.27395376,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"08 － 0197","desc":"市繁華街の中町通りに面して建つ，間口７．２ｍ，奥行２０ｍ規模のいわゆる看板建築。正面２階には両端にコリント式，その内側にイオニア式の柱頭を意識した柱形を現し，さらにデンティル付のコーニス，三角ペディメントをあしらうなど，重厚な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004909"},{"id":"00010256","register_sub_id":"101","register_pk":"199030","name":"鈴木新平商店座敷棟","kana":"すずきしんぺいしょうてんざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町109-1","lat":36.303238,"lng":139.876061,"geo_status":"db","era":"明治16年頃","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0262","desc":"見世蔵の西側に廊下を介して東西棟で建ち、木造平屋建、切妻造スレート葺である。外壁上部は大壁漆喰塗で、北面は腰高に簓子下見板を張り、南東面は下屋を設け、開放的な縁を廻らす。内部はトコや平書院を備えた六畳と八畳仏間とする。落ち着いた佇まいの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010256"},{"id":"00010255","register_sub_id":"101","register_pk":"199029","name":"鈴木新平商店文庫蔵","kana":"すずきしんぺいしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町109-1","lat":36.303256,"lng":139.875954,"geo_status":"db","era":"明治16年","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0261","desc":"見世蔵の北隣に、通りに妻面を向けて建つ。土蔵造二階建、切妻造桟瓦葺で、見世蔵の店舗側の南面に戸口を開いて掛子塗の扉を吊る。外壁は黒漆喰仕上げで腰を人造石洗出しとし、水切を廻らす。見世蔵と共に重厚な構えを形成する袖蔵で、商家町の風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010255"},{"id":"00010254","register_sub_id":"101","register_pk":"199028","name":"鈴木新平商店見世蔵","kana":"すずきしんぺいしょうてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町109-1","lat":36.303199,"lng":139.875962,"geo_status":"db","era":"明治16年頃","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0260","desc":"通りに西面する建ちの高い土蔵造二階建。正面に下屋を設けて格子をたて、二階軒は出桁造で軒蛇腹をつくり黒漆喰で塗込める。一階店舗では成の高い差物を桁行に渡し、二階和室に座敷飾を備えるなど旧規をよく残す。織物が盛んな結城の往時を伝える商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010254"},{"id":"00004509","register_sub_id":"101","register_pk":"105499","name":"鈴木紡績見世蔵","kana":"すずきぼうせきみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字西の宮町1355","lat":36.30460869,"lng":139.87555072,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積98㎡","structure_material":"土蔵造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0169","desc":"もと雑穀商の店舗で，街路に北面する。間口５間半奥行３間半の土蔵造平屋建。棟札から「大工棟梁中村榮次郎」が判明。瓦葺屋根は西端が寄棟造，東端が切妻造で、東側の落棟を寄棟造として外観を整える。土間の一部に床を張る他は旧状をよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004509"},{"id":"00010094","register_sub_id":"101","register_pk":"197927","name":"駿河屋宮田書店店舗兼主屋","kana":"するがやみやたしょてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県常陸太田市内堀町字内堀西2357","lat":36.542725,"lng":140.522618,"geo_status":"db","era":"文化7／昭和20頃改修","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積221㎡、門付","structure_material":"土蔵造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"08 － 0257","desc":"鯨ヶ丘の台地上に位置する街道に東面する、土蔵造の町家。前面につし二階のミセを建て、背後に、並行した棟の座敷部を建てて接続し、つしの格子窓に土戸と明障子をたてるなど、地方的特色を示す。正面南側には門を設け、商家としての佇まいを良好に残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010094"},{"id":"00010095","register_sub_id":"101","register_pk":"197928","name":"駿河屋宮田書店土蔵","kana":"するがやみやたしょてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県常陸太田市内堀町字内堀西2357","lat":36.54260888,"lng":140.52234579,"geo_status":"db","era":"明治41頃／平成24改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"08 － 0258","desc":"敷地南西隅に位置し、南北棟で建つ。土蔵造二階建で、東に下屋を設ける。基礎に江戸切仕上の花崗岩を二段積み、柱を三尺毎に立てて壁を塗る。東正面一階は黒漆喰で仕上げ、中央の開口部には、黒漆喰塗の鳥居枠を表す。当地における商家の屋敷構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010095"},{"id":"00010910","register_sub_id":"101","register_pk":"208881","name":"大子カフェ店舗兼主屋","kana":"だいごかふぇてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字本町南側689","lat":36.771338,"lng":140.353865,"geo_status":"db","era":"大正5／平成25改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺、建築面積90㎡","structure_material":"木造2階一部平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"08-0283","desc":"市街地の北に走る通りに北面して角地に建つ。北半の東西棟切妻造二階建部分を店舗、南半の南北棟寄棟造平屋建部分を住居としていた。店舗部東妻側の二階にはガラス戸を入れて高欄を付け、小屋梁を意匠的に見せており、通りの景観を彩る町家となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010910"},{"id":"00010911","register_sub_id":"101","register_pk":"208882","name":"大子カフェ土蔵","kana":"だいごかふぇどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字本町南側687-2","lat":36.771363,"lng":140.353792,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"08-0284","desc":"店舗兼主屋の西隣に南北棟で建つ二階建土蔵。もとは隣家の金物店の土蔵であったため、西に開口を設けて出入口としている。妻側の北面には二段の水切を入れ、腰には海鼠壁を貼って装飾する。白漆喰を基調としつつ、扉や開口枠などに効果的に黒漆喰を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010911"},{"id":"00002875","register_sub_id":"101","register_pk":"103865","name":"高久家住宅店舗","kana":"たかくけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁191","lat":36.277016,"lng":140.099152,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積131㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"08 － 0069","desc":"町中心部，御陣屋前通りと下宿通りの交差点北東角に建つ。桁行６間，梁間３間半規模の，寄棟造，平入，桟瓦葺の２階建で，外装をモルタル塗とし，２間おきに柱を立てた正面に，一間幅の下屋庇を付ける。改造はあるものの，外観や座敷などに往時の面影を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002875"},{"id":"00003354","register_sub_id":"101","register_pk":"104344","name":"丁子屋店舗兼住宅","kana":"ちょうじやてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県石岡市国府3-5-6","lat":36.18847528,"lng":140.27394583,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積119㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0076","desc":"東面を通りに向けて建つ妻入の商家。木造２階建で，１階は正面が店構えで側面に玄関を備え，２階はつし２階風になる。桟瓦葺屋根は正面寄棟造，背面切妻造で，正面に下屋庇をつける。巧みな軒廻りや，重厚な漆喰塗の外壁は，町並景観の際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003354"},{"id":"00004321","register_sub_id":"101","register_pk":"105311","name":"塚本家住宅見世蔵","kana":"つかもとけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁60","lat":36.27655955,"lng":140.1012048,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0151","desc":"敷地南端接道部分の西側に建つ。桁行５間半梁間２間の規模を有する木造平屋建で，切妻造，桟瓦葺，平入とし，棟を東西に置く。内部は土間，板の間，帳場に分かれ，南面に下屋を張出し，北面は主屋と接続する。土蔵等とともに商家の往時の佇まいを良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004321"},{"id":"00001997","register_sub_id":"101","register_pk":"102987","name":"塚本茶舗脇蔵","kana":"つかもとちゃほわきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁213-1","lat":36.27732616,"lng":140.09928172,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0047","desc":"塚本家は昭和初期に飯塚家より当地を得，塩の卸商を始め，戦後に茶舗を開業した。切妻造・桟瓦葺の脇蔵はもと飯塚家の文庫蔵で，桁行３間半，梁間２間の総２階建。妻面出入口や２階窓に用いた観音扉や，良材を用いた軸組など，全体に丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001997"},{"id":"00004511","register_sub_id":"101","register_pk":"105501","name":"中澤商店見世蔵及び主屋","kana":"なかざわしょうてんみせぐらおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字穀町1538","lat":36.30578614,"lng":139.8745999,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造及び土蔵造2階一部平屋建、瓦葺、建築面積114㎡","structure_material":"木造及び土蔵造2階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0171","desc":"見世蔵は間口４間奥行２間半の土蔵造２階建で街路に西面する。切妻屋根を桟瓦葺とし，瓦葺庇が付く。２階南面窓は出桁庇と高欄で飾る。１階店舗の土間まわりや土間境の揚げ戸，２階の１４畳蔵座敷等，当初形態をよく残す。東背後には平屋建の居室が接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004511"},{"id":"00003372","register_sub_id":"101","register_pk":"104362","name":"中村家住宅見世蔵","kana":"なかむらけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町433","lat":36.27969869,"lng":140.10076821,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0094","desc":"敷地が接する南側の街路に平行して建つ。南面する木造２階建，切妻造，平入，桟瓦葺である。正面は下屋庇を設け，西端に戸袋を設けただけの開放的な構えとし，２階は観音扉付の窓をつけ，漆喰塗の外壁を簓子下見板張で覆う。端正な外観で，保存状態も良好。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003372"},{"id":"00004114","register_sub_id":"101","register_pk":"105104","name":"西岡家住宅店舗","kana":"にしおかけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字上宿町56-1","lat":36.27722748,"lng":140.10260476,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、鉄板葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0128","desc":"通りから東方に奥まって位置し，西面して建つ。桁行５間梁間３間半の平屋建で，南側桁行３間分を土間とし，北側には１０畳の帳場を設けるとともに，表半間通りは土間とする。外観は改造が大きいが，内部の土間と帳場は往時の醸造業店舗の佇まいをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004114"},{"id":"00002207","register_sub_id":"101","register_pk":"103197","name":"西岡本店米蔵","kana":"にしおかほんてんこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田6-1","lat":36.273594,"lng":140.095535,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積126㎡","structure_material":"土蔵造平屋一部2階建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0055","desc":"脇蔵の南方に位置する玄米蔵で敷地の東南隅を占める。南北棟，切妻造，桟瓦葺の平屋建土蔵で，規模は桁行８間，梁行３間とし，南側の桁行２間を中２階に造り，西側前面の１間半通りに下屋を架けて蔵前とする。脇蔵とともに造り酒屋らしい街角景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002207"},{"id":"00002205","register_sub_id":"101","register_pk":"103195","name":"西岡本店店舗","kana":"にしおかほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田6-1","lat":36.273869,"lng":140.095627,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階一部平屋建、瓦葺、建築面積189㎡","structure_material":"木造2階一部平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0053","desc":"銘酒「花の井」で知られる西岡酒造の店舗で，もと清水屋酒造の主屋。桁行７間，梁行５間半規模，桟瓦葺，切妻造の２階建で，東側半間通りを下屋とし，南に平屋建の店舗部を張り出す。改造はあるものの，外観や土間，杜氏用の座敷などに創建時の面影を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002205"},{"id":"00002206","register_sub_id":"101","register_pk":"103196","name":"西岡本店脇蔵","kana":"にしおかほんてんわきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田6-1","lat":36.273712,"lng":140.095566,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0054","desc":"店舗の南方に位置し，店舗とは棟の方向を直交させて建つ。桁行５間，梁行３間規模，切妻造，桟瓦葺の平入総２階建土蔵で，戸口は北面に設ける。白米蔵として用いられており，窓の少ない閉鎖的なつくりとする。東側通り沿い家並みの景観形成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002206"},{"id":"00002752","register_sub_id":"101","register_pk":"103742","name":"橋本旅館主屋","kana":"はしもとりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町410-1","lat":36.279083,"lng":140.102325,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積236㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0066","desc":"真壁町の市街地北にあり，記録から建設年代が判明する。角地に建つ主屋は南が正面で，２階はＬ字型平面になり，屋根も正面入母屋造で西側部で後方に大棟が延びる。正面は中央玄関の庇や開放的な２階開口部の扱い及び手摺などに旅館建築の特徴が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002752"},{"id":"00002753","register_sub_id":"101","register_pk":"103743","name":"橋本旅館土蔵","kana":"はしもとりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町410-1","lat":36.27924476,"lng":140.1024098,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0067","desc":"主屋の北西後方に連続して建つ。桁行３間，梁間２間，切妻造・桟瓦葺，平入で，１階戸口は主屋に面した南面に設ける。外壁は白漆喰塗であるが，鉢巻から下を簓子下見板張で覆っている。小規模だがつくりは丁寧で，街路景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002753"},{"id":"00004202","register_sub_id":"101","register_pk":"105192","name":"久松商店店舗兼住宅","kana":"ひさまつしょうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-4-21","lat":36.18882086,"lng":140.2743158,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積136㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0135","desc":"中町通りに西面して建つ。正面４間奥行４間規模の店舗の奥に，床付き１０畳座敷，通り土間などを配し，店舗２階に客間を設ける。昭和４年大火後の復興看板建築で，正面両脇柱型は筋面タイル芋目地張，上部蛇腹等はモルタル塗で，壁面はもと銅板張と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004202"},{"id":"00004117","register_sub_id":"101","register_pk":"105107","name":"平井家住宅店舗及び主屋","kana":"ひらいけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁264","lat":36.27902914,"lng":140.09697786,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0131","desc":"Ｔ字路の西南角地に位置し，北面して建つ。店舗は桁行４間半梁間２間，東西棟，切妻造，桟瓦葺の木造２階建で，前面に約５尺の下屋庇を付け，奥に６畳と床付き８畳から成る角屋状の主屋を張り出す。隣家沿いの西面を土蔵風に仕上げているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004117"},{"id":"00004118","register_sub_id":"101","register_pk":"105108","name":"平井家住宅土蔵","kana":"ひらいけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁264","lat":36.27878762,"lng":140.09687872,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0132","desc":"主屋東南隅から道路に沿って南に延びる通り庭及び長屋門に続いて南北棟で建つ。桁行４間梁間２間規模，切妻造，桟瓦葺の平入２階建土蔵で，西面に戸口を設け，１階を土間床，南側半分に２階床を張る。棟木に「明治廿六年第六月 棟梁柴初五郎」と記す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004118"},{"id":"00004201","register_sub_id":"101","register_pk":"105191","name":"平松理容店店舗兼住宅","kana":"ひらまつりようてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市府中2-7-20","lat":36.190277,"lng":140.272919,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積84㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0134","desc":"市街中心地の中町通りから西に入った通りに北面して建つ。昭和４年大火の罹災を免れた建造物のひとつ。正面２間半奥行２間半の理容室の奥に和室３室などを１列に配する。正面を擬石で洋風に仕上げた看板建築で，改造はあるが内外とも往時の様子をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004201"},{"id":"00003353","register_sub_id":"101","register_pk":"104343","name":"福島屋砂糖店店舗兼住宅","kana":"ふくしまやさとうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-4-20","lat":36.18874,"lng":140.274338,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積146㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0075","desc":"通りに面して建つ商家建築。桟瓦葺，切妻造，平入の２階建で，正面に下屋庇を設ける。棟瓦を高く積んだ大棟，出桁で３段蛇腹とした２階軒，黒塗の外壁が重厚な外観をつくっている。外壁は通常の土壁漆喰塗でなく，コンクリートを用いている点が珍しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003353"},{"id":"00004203","register_sub_id":"101","register_pk":"105193","name":"府中誉主屋","kana":"ふちゅうほまれしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.1856389,"lng":140.27492659,"geo_status":"db","era":"明治2","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造一部土蔵造2階建、瓦葺、建築面積208㎡","structure_material":"木造一部土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0136","desc":"南北に長い敷地の北寄りに建つ。１階は桁行７間梁行７間半の規模で，東面してミセ及び帳場等を配し，西側に座敷等を並べる。２階は北を切妻，南を寄棟とした桟瓦葺で，１階２階とも街路に面した北面廻りを塗込めて防火的なつくりとしているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004203"},{"id":"00002877","register_sub_id":"101","register_pk":"103867","name":"星野家住宅店舗及び主屋","kana":"ほしのけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁288","lat":36.278709,"lng":140.098297,"geo_status":"db","era":"明治中期／昭和初期改造","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階及び平屋建、瓦葺、建築面積109㎡","structure_material":"木造2階及び平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"08 － 0071","desc":"町中心部，高上町通り北側に南面して建つ。桁行４間半，梁間３間規模の書院造風の主屋と，桁行４間，梁間３間半の切妻造，平入店舗から成り，店舗は２階部分を真壁造とし，正面全面に下屋庇を設ける。ショーウィンドーが昭和初期商家の店構えをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002877"},{"id":"00003502","register_sub_id":"101","register_pk":"104492","name":"増渕家住宅店舗","kana":"ますぶちけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁396","lat":36.27862666,"lng":140.1023948,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0107","desc":"旧古城村の西端に位置し，通りに西面して建つ。桁行４間半，梁間２間半の規模で，前面に約４尺の下屋庇を設ける。切妻造，桟瓦葺で，妻面の外装を簓子下見板張とする。出桁端を破風飾りで隠し二階戸袋に良質な欅材を用いるなど，街路景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003502"},{"id":"00003359","register_sub_id":"101","register_pk":"104349","name":"宮本家住宅店蔵","kana":"みやもとけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県つくば市北条188","lat":36.17764766,"lng":140.09315255,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0081","desc":"北側の街路に面して建つ土蔵造の商家建築で，保存状態が良好。木造２階建，切妻造，平入で，北と西に下屋を設け，東には蔵を附属し，屋根は桟瓦葺とする。東面は簓子下見板張だが，他は軒裏まで丁寧な漆喰塗とし，正面２階の窓の観音扉など，重厚感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003359"},{"id":"00001863","register_sub_id":"101","register_pk":"102853","name":"三輪家住宅見世蔵","kana":"みわけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁229","lat":36.278305,"lng":140.098633,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0036","desc":"三輪家は真壁町の中心，高上町通南側に位置する。北面して建つ見世蔵は，桁行３間・梁間２間，正面下屋庇付の切妻造・平入の土蔵造建築。白漆喰壁や高い箱棟など重厚であるが，正面は１・２階とも片側に戸袋を設けて，開放的な近代の商家のつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001863"},{"id":"00009574","register_sub_id":"101","register_pk":"194570","name":"武蔵屋店舗","kana":"むさしやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県古河市横山町1-5535-2","lat":36.19731836,"lng":139.70469457,"geo_status":"db","era":"明治中期／平成23改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積72㎡、門付","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"08 － 0256","desc":"旧日光街道古河宿に西面して建つ。土蔵造二階建、寄棟造桟瓦葺で、正面を下屋とする。外壁黒塗で軒まで塗込め、腰を石貼とする。二階前面に開放的な縁側を通し、手摺を設け、戸袋を銅板張とする。堅牢かつ重厚な外観をもつ料理屋建築で、宿場の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009574"},{"id":"00004325","register_sub_id":"101","register_pk":"105315","name":"村井醸造店舗","kana":"むらいじょうぞうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁72","lat":36.276459,"lng":140.100128,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積231㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0155","desc":"上宿通りより入る門の正面に構える大規模な土蔵造店舗。桁行９間梁間６間（西半分は８間），切妻造，桟瓦葺，２階建で，東西棟の東半分を落屋根とする。外壁は白漆喰で仕上げ，腰まで簓子下見板張とする。旧市街に残る造り酒屋の中心的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004325"},{"id":"00004696","register_sub_id":"101","register_pk":"105686","name":"村上家住宅主屋","kana":"むらかみけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字高上町232","lat":36.27824,"lng":140.097977,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積135㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0181","desc":"町中心部の高上町に位置し，南北の通りに西面する敷地の西北部に建つ。桁行６間梁間２間半，南北棟，切妻造，桟瓦葺，平入の平屋建で，前面に下屋を付けた店舗の東奥に東西棟，寄棟造で８畳２室の座敷棟が続き，東南方に東西棟，寄棟造の台所棟を突出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004696"},{"id":"00003497","register_sub_id":"101","register_pk":"104487","name":"森戸文四郎商店店舗兼住宅","kana":"もりとぶんしろうしょうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府三丁目695-1","lat":36.18956552,"lng":140.27397107,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積153㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0102","desc":"市繁華街の中町通りに面して建つ。間口４間，奥行１５間で，正面をモルタル塗とする。一階に広く開口部をとり，二階部分の中央３柱型間にレリーフと縦長窓を配し，隅部の柱形には褐色タイルを張る。全体でアールデコ調の外観を呈するいわゆる看板建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003497"},{"id":"00004709","register_sub_id":"101","register_pk":"105699","name":"谷口家住宅石蔵","kana":"やぐちけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町桜井172","lat":36.28114552,"lng":140.10414028,"geo_status":"db","era":"大正初期／大正後期増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造一部煉瓦造平屋建、瓦葺、建築面積72㎡","structure_material":"石造一部煉瓦造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0194","desc":"店舗の通りを隔てた向かいの敷地に位置する。桁行６間梁間３間規模，南北棟，寄棟造，桟瓦葺の石造もと２階建で，西面に煉瓦造の旧繭乾燥室を添わす。石蔵の石材は花崗岩で，一つ一つの石に面を取り，軒蛇腹や胴蛇腹に刳型を施すなど精緻なつくりで際立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004709"},{"id":"00004710","register_sub_id":"101","register_pk":"105700","name":"谷口家住宅奥蔵","kana":"やぐちけじゅうたくおくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井172","lat":36.281071,"lng":140.10391531,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積83㎡","structure_material":"土蔵造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0195","desc":"通りの西側の敷地に位置し，石蔵の西南方に南北棟で建つ。桁行６間半梁間３間規模，切妻造，桟瓦葺の平屋建土蔵で，東面北寄りに土庇を差し掛け観音開きの防火扉を備えた戸口を設ける。北妻面に１箇所，南妻面に２箇所，西面に３箇所と窓が多いのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004710"},{"id":"00001553","register_sub_id":"101","register_pk":"102543","name":"谷口家住宅北袖蔵","kana":"やぐちけじゅうたくきたそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.28109,"lng":140.10434,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0025","desc":"江戸初期から続く谷口家は名主もつとめた旧家で，江戸末期には絞油業・醤油醸造業を営んでいた。店舗北側の北袖蔵は，江戸末期の建築と考えられる。東西棟の切妻造・桟瓦葺で，１階店舗側，２階道側に設けた観音扉，高い瓦棟積など，重厚なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001553"},{"id":"00004711","register_sub_id":"101","register_pk":"105701","name":"谷口家住宅穀蔵","kana":"やぐちけじゅうたくこくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井172","lat":36.28101079,"lng":140.10405476,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積66㎡","structure_material":"土蔵造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0196","desc":"奥蔵の東方に位置し，南北棟で建つ。桁行６間梁間３間，切妻造，桟瓦葺のたちの高い平屋建土蔵で，通り側の東面北寄りに奥行１間の下屋を架け，観音開きの防火戸を吊りこんだ戸口を設ける。窓は南北妻面の高い位置に開けられ，ともに観音開きの防火扉を吊る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004711"},{"id":"00001552","register_sub_id":"101","register_pk":"102542","name":"谷口家住宅店舗","kana":"やぐちけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.28101758,"lng":140.10436898,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0024","desc":"明治期に製糸業を営んだ谷口家は，県内有数の製糸所となった。店舗は棟札より，明治３３年の建築とわかり，棟梁は地元の増渕市太郎。旧道に西面して建つ寄棟造・妻入の形式で，１階のＬ字型土間に商家の店構えがみられ，後面は江戸末期の主屋と接続している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001552"},{"id":"00001554","register_sub_id":"101","register_pk":"102544","name":"谷口家住宅南袖蔵","kana":"やぐちけじゅうたくみなみそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.28090736,"lng":140.10428309,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0026","desc":"店舗南側に少し離れて建つ南袖蔵は，店舗建立後，遅れて建設されたと伝える。形式は北袖蔵と同じで，東西棟の切妻造・桟瓦葺，軒に鉢巻を廻し，外壁が簓子下見板張。観音扉や高い瓦棟積なども共通するが，規模はひとまわり大きく，保存状態も良好。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001554"},{"id":"00001555","register_sub_id":"101","register_pk":"102545","name":"谷口家住宅門","kana":"やぐちけじゅうたくもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.2809744,"lng":140.10433693,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"薬医門、瓦葺、間口2.7m","structure_material":"薬医門","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0027","desc":"桁行１間梁間１間の薬医門で，内開き板戸をつけ，両側に通用門を設ける。店舗と南袖蔵を繋ぐ位置に建ち，建設年代は南袖蔵と同じ頃とみられる。切妻造・桟瓦葺の大屋根は棟積や降棟を凝った意匠として，屋敷の正門に相応しい格式をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001555"},{"id":"00004705","register_sub_id":"101","register_pk":"105695","name":"谷口義衛家住宅長屋門及び主屋","kana":"やぐちよしえけじゅうたくながやもんおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井1","lat":36.28040548,"lng":140.10376239,"geo_status":"db","era":"明治初期／明治25頃移築増改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0190","desc":"近隣の旧雨引村から移築した長屋門の門口右手に下屋庇を付けて店舗風に改造し，その背後に居住部を増築。長屋門は，桁行１０間５尺梁行２間半規模，寄棟造，桟瓦葺の平屋建で，正面左側桁行２間半分を物置とする。門口の軒を３段の出桁造とするのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004705"},{"id":"00010737","register_sub_id":"101","register_pk":"201572","name":"祐月本店雛蔵","kana":"ゆうげつほんてんひなぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県水戸市末広町二丁目2282-1","lat":36.38972,"lng":140.454966,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0272","desc":"南北棟の二階建土蔵で切妻造桟瓦葺。大谷石布積の基礎に黒漆喰塗の外壁を立上げ、小屋は和小屋組とし、軒に鉢巻を廻す。東面と主屋側の南妻面は一階に扉口を開け、二階に持送り付の小庇をもつ窓を設ける。桁行六間と規模が大きく、重厚かつ丁寧な施工の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010737"},{"id":"00004504","register_sub_id":"101","register_pk":"105494","name":"結真紬見世蔵","kana":"ゆうしんつむぎみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町68-1","lat":36.30383866,"lng":139.87499993,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0164","desc":"もと呉服店で街路に北面する。間口４間半奥行３間，土蔵造２階建の平入町家。切妻屋根を桟瓦葺とし，正面に瓦庇が付く。外壁は黒漆喰塗である。正面１階は両脇半間が壁で、ガラス戸を建て込み，２階は格子窓とする。市街に遺る貴重な見世蔵のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004504"},{"id":"00002363","register_sub_id":"101","register_pk":"103353","name":"芥川荘","kana":"あくたがわそう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県長生郡一宮町一宮字林下9240-1","lat":35.38116777,"lng":140.38554778,"geo_status":"db","era":"明治30代","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、茅葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"12 － 0039","desc":"避暑地として開発された海岸地区に建つ。平屋建，寄棟造，茅葺で，主室，次の間２室の３方に縁を回らし，縁の一端に洗面所を付す。当地方の伝統的な民家建築の技法になり，周囲の松林と相俟って良好な景観をなす。芥川龍之介が滞在したことでこの名がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002363"},{"id":"00001246","register_sub_id":"101","register_pk":"102236","name":"熱海輪店（旧千葉銀行大網支店）","kana":"あたみりんてん（きゅうちばぎんこうおおあみしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県山武郡大網白里町大網686-1","lat":35.52538448,"lng":140.32126369,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造２階建，瓦葺，建築面積48㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"12 － 0027","desc":"木造２階建の銀行建築。近年の改装で、モルタル塗石目地仕上げがタイル貼りに変ったが、大正期銀行建築の骨格は旧状を留める。パラペット中央にスクロールを従え、中心に紋章飾りを据えた半円アーチのゲーブルを立上げてファサードに見せ所をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001246"},{"id":"00001170","register_sub_id":"101","register_pk":"102160","name":"新井時計店","kana":"あらいとけいてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県匝瑳市八日市場イ2450","lat":35.701805,"lng":140.549469,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造２階建，瓦葺，建築面積42㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0012","desc":"東金と銚子を結ぶ街道沿い、八日市場本町通り商店街の東寄りに南面して建つ。木造２階建、切妻妻入、モルタル塗の看板建築で、妻面を洋風ペジメントに仕上げ、軒蛇腹下に沿ってネオンサインを掲げる。昭和初期の商店街の面影を伝える遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001170"},{"id":"00007615","register_sub_id":"101","register_pk":"108597","name":"伊勢幸酒店店舗兼主屋","kana":"いせこうしゅてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町久保字根古屋132","lat":35.28652514,"lng":140.24649093,"geo_status":"db","era":"明治6／大正10・昭和45改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0123","desc":"大多喜城下の商人町に所在し、通りに東面して建つ。寄棟造平入の木造２階建で、正面及び北面に下屋庇、南面に玄関を付け、背面に平屋建を突き出す。１階は店舗で間口を大きく開き、２階正面は全面に格子戸をたて込む。城下における商家の表構えをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007615"},{"id":"00007970","register_sub_id":"101","register_pk":"128803","name":"一粒丸三橋薬局店舗","kana":"いちりゅうがんみつはしやっきょくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県成田市仲町363","lat":35.78432647,"lng":140.31730224,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"12-0139","desc":"南北に長い敷地で、成田山参道に北面する。土蔵造２階建で、東西棟の切妻造桟瓦葺。間口８．７ｍの町家。正面は下屋庇を張り出し、黒漆喰仕上げ。１階を広く開放し、２階には掛子塗の両開扉を吊った窓を２ヶ所開ける。土壁で塗り込めた重厚な店蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007970"},{"id":"00007971","register_sub_id":"101","register_pk":"128804","name":"一粒丸三橋薬局土蔵","kana":"いちりゅうがんみつはしやっきょくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県成田市仲町363","lat":35.78415834,"lng":140.31742322,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"12-0140","desc":"店舗の南方に中庭を挟んで西面して建つ。桁行６．４ｍ梁間３．６ｍの土蔵造２階建、南北棟の切妻造桟瓦葺。白漆喰仕上げで、西面に庇を付け、中央に掛子塗の両開戸を吊り、２階には窓を穿つ。鬼瓦に影盛を施し、大棟を複雑な組棟とし、外観を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007971"},{"id":"00006501","register_sub_id":"101","register_pk":"107484","name":"岩井家住宅主屋（旧武蔵屋店舗）","kana":"いわいけじゅうたくしゅおく（きゅうむさしやてんぽ）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県印西市木下1645","lat":35.83975553,"lng":140.14784573,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積99㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"12 － 0089","desc":"通りに南面して、桁行５間半梁間３間、切妻造桟瓦葺２階建を建て、その北側に桁行２間半梁間５間半の切妻造桟瓦葺平屋建を直角に付ける。通り側に広く土間、２階と背面突出部に居室をとる。１階土間まわりや２階の手摺付縁などに旅籠の雰囲気を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006501"},{"id":"00001181","register_sub_id":"101","register_pk":"102171","name":"大屋旅館","kana":"おおやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁64","lat":35.28292566,"lng":140.24733,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造２階建，瓦葺，建築面積297㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0023","desc":"夷隅神社を核として形成された大多喜城下の新丁地区の、参道脇に位置する門前宿。木造２階建、南北棟、瓦葺切妻屋根、平入の宿屋で、正面２階左右の戸袋に大きく屋号を漆喰で表している。正岡子規が学生時代に泊まったことでも知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001181"},{"id":"00010924","register_sub_id":"101","register_pk":"208895","name":"小高記念館","kana":"おだかきねんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県館山市館山95-70","lat":34.986153,"lng":139.852095,"geo_status":"db","era":"大正期／昭和5頃移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、鉄板葺、建築面積64㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"12-0186","desc":"当初銀行建築として建てられたものを館山港に程近い現在地へ移築したと伝わる。木造二階建で上下窓を並べる洋風外観を持つ。北西隅を切って玄関を開く。一階はもと営業室で、洋風内装とし、二階には一〇畳の和室二間を並べる。港町の風情を彩る洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010924"},{"id":"00013231","register_sub_id":"101","register_pk":"366220","name":"川豊本店店舗","kana":"かわとよほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県成田市仲町386-1","lat":35.78340278,"lng":140.31672222,"geo_status":"db","era":"明治44年頃／大正15年増築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造3階建、金属板葺、建築面積146㎡","structure_material":"木造3階建","registered":"2020.04.03(令和2.04.03)","register_no":"12 － 0297","desc":"成田山新勝寺の参道に西面して建つ、木造三階建、入母屋造金属板葺平入の店鋪。大正期の旅館開業に際し三階を増築した。正面外観は木製建具で開放し、二、三階内部は旅館客室の床回りなどの造作が良く残る。ひと際高い建物は、門前町の景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013231"},{"id":"00001346","register_sub_id":"101","register_pk":"102336","name":"木内家住宅旧店舗","kana":"きうちけじゅうたくきゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県香取郡多古町多古2613","lat":35.73796179,"lng":140.46582959,"geo_status":"db","era":"昭和4～6","year":1929,"year_source":"converted","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造2階建、銅板葺、建築面積45㎡","structure_material":"石造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"12 － 0033","desc":"通りに面して建つ店舗は切妻造・平入，銅板葺で，通り側に下屋庇を設け，商家の店構えらしく，開口部を多くとる。１階は大谷石積であるが，２階は和風の木造として，伝統と流行が折衷した意匠となっており，この地域の近代商家建築の展開をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001346"},{"id":"00014325","register_sub_id":"101","register_pk":"511314","name":"旧莇家住宅店舗兼主屋","kana":"きゅうあざみけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県印旛郡酒々井町酒々井字上宿1636-1","lat":35.723225,"lng":140.26562778,"geo_status":"db","era":"明治中期／同40年増築・昭和28年改修・平成30年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積147㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"12 - 0322","desc":"佐倉街道の酒々井宿に所在する醤油や茶の商家。重厚な土蔵造の二階建で、正面格子戸の１階は土間とミセ、高欄付の２階は床構え付の広い座敷とする。角屋で背面に仏間や内向き座敷、土間の妻側に添蔵を設ける。賑わった街道の歴史的景観を伝える豪壮な店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014325"},{"id":"00013047","register_sub_id":"101","register_pk":"368232","name":"旧今井家住宅座敷棟","kana":"きゅういまいけじゅうたくざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県佐倉市新町字仲町北側48-1","lat":35.71966389,"lng":140.23080556,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"12 － 0295","desc":"主屋の背面に接続し、南北棟で建つ。北側を寄棟造、南の主屋側を両下造とする。東面南寄りに玄関を設け、四室を食違に配する。六畳主室には床と違棚を設け、壁を鼠漆喰で塗り、天井も幅広の板をふんだんに使うなど上質なつくりの座敷棟である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013047"},{"id":"00013046","register_sub_id":"101","register_pk":"368231","name":"旧今井家住宅主屋","kana":"きゅういまいけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県佐倉市新町字仲町北側48-1","lat":35.71960278,"lng":140.23081111,"geo_status":"db","era":"明治中期／明治後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"12 － 0294","desc":"旧佐倉城下の町人地で新町通りに南面して建つ元呉服店。妻入で正面を寄棟造として深い下屋を付し、背面は切妻造で座敷棟に接続する。前面のミセは前土間とし、通り土間を持たず床上部から後方ので居住部に続く平面とする。佐倉の商家の佇まいを良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013046"},{"id":"00013048","register_sub_id":"101","register_pk":"368233","name":"旧今井家住宅土蔵","kana":"きゅういまいけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県佐倉市新町字仲町北側48-1","lat":35.71976111,"lng":140.23078333,"geo_status":"db","era":"明治25年／平成23年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"12 － 0296","desc":"南北に長い敷地の中ほどに南北棟で建つ土蔵。妻入で、南正面に下屋を付して出入口を開ける。二階は正背面に庇付の窓を設け、土戸を両開きとする。土戸は丁寧な掛子塗仕上で、高い左官技術がうかがえる。鬼瓦には影盛を施し、地域的な特色を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013048"},{"id":"00007730","register_sub_id":"101","register_pk":"108712","name":"旧河内屋店舗及び主屋","kana":"きゅうかわちやてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県君津市久留里市場字仲町158-1他","lat":35.29535827,"lng":140.07780272,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積135㎡","structure_material":"木造平屋一部2階建","registered":"2009.08.07(平成21.08.07)","register_no":"12-0125","desc":"通りに西面して建つ。間口７．３ｍの商家で、正面に切妻造平入のミセ、後方に木造２階建を設け、その間を両下造で繋ぐ。ミセは内法の高い格天井の一室で、当初は後寄りに低い床を張った。正面は出桁造とし、下屋庇を付け、棟を高く積み、重厚な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007730"},{"id":"00011075","register_sub_id":"101","register_pk":"205182","name":"旧平井家住宅座敷棟","kana":"きゅうひらいけじゅうたくざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県佐倉市新町233-5","lat":35.719052,"lng":140.227435,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"12 - 0189","desc":"平屋建、瓦葺で、棟を東西に通し、西側は寄棟とし、東側は主屋背面に接する。ブツマ、オクノマを東西に並べ、南面と西面に縁を回す。さらに西側には、床や腰壁に大理石を用いた上便所が付属する。年代が明らかであり、商家の暮らしぶりをよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011075"},{"id":"00011074","register_sub_id":"101","register_pk":"205181","name":"旧平井家住宅店舗兼主屋","kana":"きゅうひらいけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県佐倉市新町233-5","lat":35.719056,"lng":140.227526,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"12 - 0188","desc":"商家町の角地に東面して建つ町家。南北棟の平入、切妻造桟瓦葺二階建。一階正面は開放的なミセとし、揚戸の痕跡が残っている。一階奥側のチャノマなどと、二階を居住空間とする。街道の要衝に位置し、佐倉旧城下の歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011074"},{"id":"00011076","register_sub_id":"101","register_pk":"205183","name":"旧平井家住宅脇蔵","kana":"きゅうひらいけじゅうたくわきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県佐倉市新町233-6","lat":35.718989,"lng":140.227558,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"12 - 0190","desc":"店舗兼主屋に隣接し、東面して建つ。土蔵造二階建。正面の下屋は腰を人造石研ぎ出し仕上げとし、二階部分を漆喰塗とする。土蔵内部に階段はなく、二階北側の出入り口で主屋と接続する。大八車を収めていたと伝える蔵で、商家の屋敷構成をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011076"},{"id":"00004335","register_sub_id":"101","register_pk":"105325","name":"呉服新川屋店舗","kana":"ごふくしんかわやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県流山市加6-1305","lat":35.85751955,"lng":139.89969463,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"12 － 0058","desc":"流山広小路に東面して建つ。間口４間半規模，南北棟，切妻造，桟瓦葺の平入２階建店蔵で，正面２階を黒漆喰塗，妻面は押縁下見板張とする。大工は土屋熊五郎。大正期の道路拡幅により正面下屋が削られているが，江戸川沿い物資集散地の繁栄振りを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004335"},{"id":"00001169","register_sub_id":"101","register_pk":"102159","name":"坂本総本店店舗","kana":"さかもとそうほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県匝瑳市八日市場イ2474","lat":35.70132014,"lng":140.54791366,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積40㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0011","desc":"総武本線八日市場駅の北西方、東金と銚子を結ぶ街道沿いに建つ黒漆喰塗、切妻平入、二階建の土蔵造り店舗建築。地棟下端の墨書により建設年と棟梁名（大木某）等が判明する。八日市場の往時の街道景観を偲ばせる遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001169"},{"id":"00010120","register_sub_id":"101","register_pk":"197953","name":"笹屋土蔵","kana":"ささやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県流山市流山1-155-1","lat":35.857249,"lng":139.899925,"geo_status":"db","era":"明治31／平成24改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0180","desc":"土蔵造二階建、桁行六・四メートル梁間四・五メートルの東西棟で、切妻造桟瓦葺とする。西妻に両開土戸の戸口を開く。外壁は漆喰塗で、鉢巻と腰を黒漆喰塗で引締める。小屋組は二重梁で棟木下に桁行梁を二段挿入する。旧道沿いの往時の賑わいを伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010120"},{"id":"00010121","register_sub_id":"101","register_pk":"197954","name":"清水屋本店店舗兼主屋","kana":"しみずやほんてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県流山市流山2-26","lat":35.85551,"lng":139.898141,"geo_status":"db","era":"明治中期／昭和8頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積101㎡","structure_material":"木造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0181","desc":"旧街道に東面する和菓子店舗で、背面北寄りに寄棟造平屋建の住居部を突出し、正面庇上にモルタル塗看板を立上げる。二階の軒は浅い出桁造とし、南面窓の腰高さに高欄がつく。店舗の土間床に建つ独立円柱は脚部を大理石塗とする。戦前の店舗建築の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010121"},{"id":"00001244","register_sub_id":"101","register_pk":"102234","name":"染織処谷屋土蔵（夢紫美術館）","kana":"そめおりどころたにやどぞう（ゆめむらさきびじゅつかん）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県香取市小見川580","lat":35.85486128,"lng":140.60749872,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造２階建，瓦葺，建築面積20㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"12 － 0025","desc":"利根川支流黒部川の舟運で栄えた小見川町の代表的商家の土蔵で、旧銚子街道に南面して建つ。南北棟、瓦葺２階建、平入で、店舗側の東面に蔵前を設け、西面は板貼とする外観上は標準的造りの土蔵であるが、洪水に備えて床高を上げるなどの工夫も見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001244"},{"id":"00001348","register_sub_id":"101","register_pk":"102338","name":"多田屋店舗","kana":"ただやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1136","lat":35.56159752,"lng":140.36233738,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積92㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"12 － 0030","desc":"多田屋は文化２年創業の書店で，県下で最も古い。現在の店舗は昭和初期の建築と推測され，木造モルタル塗，総２階建である。腰部は切石積であるが，溝が入った柱型や軒の持ち送りなどは石造を模したもので，全体に古典主義様式建築を意識している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001348"},{"id":"00000235","register_sub_id":"101","register_pk":"101225","name":"千葉トヨペット本社（旧勧業銀行本店）","kana":"ちばとよぺっとほんしゃ（きゅうかんぎょうぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県千葉市美浜区稲毛海岸4-5-1","lat":35.63647736,"lng":140.07788459,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建，瓦葺，建築面積1320㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"12 － 0004","desc":"木造２階建の事務所建築。当初銀行社屋として建てられ、数度の移築を経ている。唐破風をもつ中央の玄関から左右対称に展開し、全体の意匠は和風を基調としている。設計は妻木頼黄と武田五一による。国道に面して建つ特異な外観をもつ大規模な建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000235"},{"id":"00008651","register_sub_id":"101","register_pk":"149372","name":"寺田園旧店舗","kana":"てらだえんきゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県流山市流山二丁目101-1","lat":35.85536961,"lng":139.89834497,"geo_status":"db","era":"明治22年","year":1889,"year_source":"converted","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"12 － 0154","desc":"江戸川沿いの市街地の中心に位置し、通りに西面する。土蔵造2階建の前後に深い下屋を張り出し、正面7.3ｍ奥行8.5ｍの規模とする。寄棟造桟瓦葺。前寄りを広くミセとし、後方や2階に居室や台所を配する。黒漆喰仕上げになる本格的な蔵造店舗である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008651"},{"id":"00006377","register_sub_id":"101","register_pk":"107360","name":"戸邉五右衞門家住宅米蔵","kana":"とべごえもんけじゅうたくこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県野田市中野台字川岸702-1他","lat":35.939816,"lng":139.84915684,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0088","desc":"主屋の東南、通り沿いに位置する。桁行５間、梁間２間の寄棟造妻入桟瓦葺の平屋建である。外壁はモルタル塗。内部は桁行で２分され、入口側は米や味噌などを収蔵する蔵、背面側は養蚕部屋として使用されたという。歴史的な屋敷構えを構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006377"},{"id":"00006745","register_sub_id":"101","register_pk":"107728","name":"戸邉五右衞門家住宅主屋","kana":"とべごえもんけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市中野台字川岸699-3他","lat":35.940002,"lng":139.849106,"geo_status":"db","era":"明治26頃／昭和4頃増築・24曳家","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積216㎡","structure_material":"木造平屋一部2階建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0085","desc":"江戸川の野田上河岸にあった河岸問屋で、河川改修に伴い曳家された。桁行８間半、梁間６間の大規模な建築で、寄棟造桟瓦葺とする。増築された２階建の洋館は外壁モルタル塗で、２階に縦長窓を配した応接室を設ける。良質な遺構で、河岸の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006745"},{"id":"00006376","register_sub_id":"101","register_pk":"107359","name":"戸邉五右衞門家住宅倉庫","kana":"とべごえもんけじゅうたくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県野田市中野台字川岸703-1","lat":35.939911,"lng":139.848907,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積103㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0087","desc":"主屋の西南、江戸川堤防に面して建つ。桁行８間、梁間３間と規模の大きな倉庫で、寄棟造桟瓦葺とし、平側に吹抜け下屋を設ける。外壁はモルタル塗一部下見板張。内部は桁行で２分され、川側に居室、主屋側には吹抜けの広い収納スペースを設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006376"},{"id":"00006375","register_sub_id":"101","register_pk":"107358","name":"戸邉五右衞門家住宅土蔵","kana":"とべごえもんけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県野田市中野台字川岸702-1","lat":35.940083,"lng":139.848938,"geo_status":"db","era":"昭和4／昭和24曳家","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0086","desc":"洋館の奥に建ち、洋館との間に蔵前を設ける。桁行３間、梁間２間、土蔵造の切妻造妻入桟瓦葺で、２階建とし、１階床下も物入として利用する。外壁は漆喰仕上げ。重厚ななかに、庇付の窓や太い折釘、２段に作られた水切りなどが変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006375"},{"id":"00007612","register_sub_id":"101","register_pk":"108594","name":"八鶴亭宿泊館","kana":"はっかくていしゅくはくかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.56067322,"lng":140.35903601,"geo_status":"db","era":"大正7頃／昭和54頃改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0120","desc":"新館の東側に接続する木造２階建。寄棟造桟瓦葺で、鉄板葺庇をまわす。Ｌ字型平面になり、１階の西側にホール、東側及び２階に宿泊室を配する。最も高い新館を中心に棟高や屋根形式が異なる本館と宿泊館３棟が並び建ち、八鶴湖の景観に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007612"},{"id":"00007611","register_sub_id":"101","register_pk":"108593","name":"八鶴亭新館","kana":"はっかくていしんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.56055684,"lng":140.35894342,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造3階建、瓦葺、建築面積104㎡","structure_material":"木造3階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0119","desc":"本館の東側に接続する木造３階建。入母屋造桟瓦葺屋根を組み合わせ、湖側にも破風を見せる。２階の二十畳は黒檀の絞り丸太をトコ柱に据え、階段室には中央に矩形に網代を張り、周囲に垂木を配る天井をつくる。部屋ごとに天井意匠や銘木を違え、変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007611"},{"id":"00007614","register_sub_id":"101","register_pk":"108596","name":"八鶴亭ビリヤード棟","kana":"はっかくていびりやーどとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.56052079,"lng":140.35913639,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0122","desc":"浴室棟の東側に接続する。桁行６．４ｍ梁間６．０ｍの木造平屋建。寄棟造で赤色の桟瓦を葺く。北にビリヤード室、南側に廊下を配する。外壁はモルタル塗に目地を入れ石積を模し、角に柱型を表す。和風建築群において、石造風外壁と赤瓦が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007614"},{"id":"00007610","register_sub_id":"101","register_pk":"108592","name":"八鶴亭本館","kana":"はっかくていほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.5605136,"lng":140.35876799,"geo_status":"db","era":"昭和前期／昭和30頃・平成17改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積414㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0118","desc":"八鶴湖岸沿いの通り南に占める敷地の西北寄りに位置する。木造２階建で、入母屋造桟瓦葺屋根を組み合わせる。１階に六十畳の大広間や玄関、配膳室、２階に宿泊室が配される。各部屋は入口に差掛け屋根を付け、トコや棚に銘木を使うなど凝った意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007610"},{"id":"00007613","register_sub_id":"101","register_pk":"108595","name":"八鶴亭浴室棟","kana":"はっかくていよくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.5604154,"lng":140.35910938,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺一部鉄板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0121","desc":"敷地南辺に建ち、渡廊下により新館に接続する。木造平屋建の寄棟造桟瓦葺で、庇と渡廊下は鉄板葺。脱衣室と大浴場、ボイラー室、家族風呂などをＬ字型に配す。家族風呂は市松文様にタイルを床に貼り、内壁に三階菱や円形の開口を設けるなど装飾する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007613"},{"id":"00003392","register_sub_id":"101","register_pk":"104382","name":"廣瀬家住宅井戸上屋","kana":"ひろせけじゅうたくいどうわや","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県習志野市津田沼6-5-11","lat":35.678028,"lng":140.02158386,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、瓦葺、建築面積8.1㎡","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0054","desc":"倉庫北端部西方に東西棟で建つ。桁行３．３５ｍ，梁間２．４３ｍ規模で，柱は内転びに建て，四周吹き放ちとし，切妻造，桟瓦葺の屋根を載せる。かっての海岸線と旧の上総街道との間に位置する雑穀問屋の屋敷構えを構成する主要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003392"},{"id":"00003391","register_sub_id":"101","register_pk":"104381","name":"廣瀬家住宅倉庫","kana":"ひろせけじゅうたくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県習志野市津田沼6-5-11","lat":35.67797252,"lng":140.02162272,"geo_status":"db","era":"明治42／昭和10頃移築改造","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0053","desc":"敷地の東寄り中央に南北棟で建つ。桁行５間半，梁間３間規模，切妻造，桟瓦葺で，曳家時の３尺高コンクリート土台に建ち，棟に大きな鬼瓦を載せ，西面に１間幅の下屋を差し掛ける。３尺ピッチの柱間に３本の間柱を建てる「角寄せ蔵」風のつくりに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003391"},{"id":"00006280","register_sub_id":"101","register_pk":"107264","name":"紅屋商店店舗","kana":"べにやしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県館山市長須賀1","lat":34.985184,"lng":139.865814,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0071","desc":"街路にほぼ西面して建つ。木造２階建，切妻造，桟瓦葺，平入で，正面には銅板葺の下屋を設ける。塗屋造で，外壁は人造石洗出しとし，石造風に見せる。現在は１階が店舗，２階が倉庫で，１・２階とも開口部に漆喰塗等の防火扉を設ける。震災復興期の店舗建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006280"},{"id":"00001179","register_sub_id":"101","register_pk":"102169","name":"星野家薬局調剤室","kana":"ほしのけやっきょくちょうざいしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県長生郡長南町長南2574","lat":35.3981938,"lng":140.23167255,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積15㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0021","desc":"店舗の北に１間分の通路を隔てて建つ２階建、瓦葺切妻屋根、平入の土蔵で、間口２間の妻を街道に向け、街道沿いの前面に２棟を繋ぐように庇を架ける。この庇は千葉県博覧図にも描かれており当初から店舗と一体的につくられたものと推測される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001179"},{"id":"00001178","register_sub_id":"101","register_pk":"102168","name":"星野家薬局店舗","kana":"ほしのけやっきょくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県長生郡長南町長南2574","lat":35.39813217,"lng":140.23171359,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積30㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0020","desc":"房総往還道の宿場町として栄えた長南宿の中央部に位置する商家。間口４間、奥行３間半の２階建、黒漆喰塗、瓦葺切妻屋根、妻入の土蔵造店舗で、正面サッシュ類を除いて、明治２８年の千葉県博覧図に描かれた外観とほとんど異なるところがない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001178"},{"id":"00006374","register_sub_id":"101","register_pk":"107357","name":"桝田家住宅主屋","kana":"ますだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市今上字浅間下2574-1","lat":35.936882,"lng":139.854416,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積185㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0084","desc":"西側を流れる江戸川の堤防に面して建つ。桁行９間、梁間７間の木造２階一部平屋建で、寄棟造桟瓦葺とし、背面を葺き降ろす。１階は梁間前半部が帳場や台所など商用部分、後半部が私的な部屋で、２階には舟宿の客室３室がある。江戸川の舟運の隆盛を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006374"},{"id":"00009588","register_sub_id":"101","register_pk":"194584","name":"桝田家住宅土蔵","kana":"ますだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県野田市今上字浅現下2574-1","lat":35.93686545,"lng":139.85456825,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"12 － 0164","desc":"主屋南のオクニワの東寄りに建つ土蔵造二階建で、切妻造桟瓦葺。西面戸口にモルタル塗鉄扉を吊り、下屋で主屋と接続する。外壁はモルタル塗で石造風に目地を切り、一階南面と二階南北面に鉄板葺庇付の窓を開く。小屋は二重梁の和小屋。近代的な外壁の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009588"},{"id":"00009587","register_sub_id":"101","register_pk":"194583","name":"桝田家住宅不動尊祠","kana":"ますだけじゅうたくふどうそんほこら","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県野田市今上字浅現下2574-1","lat":35.93681072,"lng":139.85456825,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平家建、瓦葺、建築面積0.6㎡","structure_material":"木造平家建","registered":"2013.06.21(平成25.06.21)","register_no":"12 － 0163","desc":"主屋南のオクニワの南東寄りに位置し、方〇・八メートル規模、切妻造桟瓦葺。乱石積基壇上に土台を伏せ、角柱を長押二段と木鼻付頭貫で固め、組物三斗実肘木、妻飾虹梁大瓶束、一軒繁垂木とし、正面は桟唐戸両開、側背面を横板壁とする、本格的なつくりの祠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009587"},{"id":"00009590","register_sub_id":"101","register_pk":"194586","name":"桝田家住宅煉瓦塀","kana":"ますだけじゅうたくれんがべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市今上字浅現下2574-1","lat":35.93682296,"lng":139.85432297,"geo_status":"db","era":"明治後期／昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、総延長39m","structure_material":"煉瓦造","registered":"2013.06.21(平成25.06.21)","register_no":"12 － 0166","desc":"屋敷西正面から南面を囲む煉瓦塀。西面は高さ一メートル。主屋の玄関と土間の前に出入口を開き、煉瓦塀端部の縦溝は、江戸川溢水時に堰板を落込む仕掛けである。脇門から南では高さ二・七メートルで、上部に歯形装飾を施し、西寄りに鉄格子付の小窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009590"},{"id":"00009589","register_sub_id":"101","register_pk":"194585","name":"桝田家住宅脇門","kana":"ますだけじゅうたくわきもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市今上字浅現下2574-1","lat":35.93678455,"lng":139.85449687,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口1.5m、左右塀付","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"12 － 0165","desc":"主屋南のオクニワの西面に開く間口一・五メートルの薬医門で、切妻造桟瓦葺。男梁に束立てで棟木を受け、一軒疎垂木とする軽快な門で、板戸を両開に吊る。左右の塀は桟瓦葺で主屋と煉瓦塀に接続し、漆喰塗で腰を羽目板張とする。丁寧なつくりの門塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009589"},{"id":"00013353","register_sub_id":"101","register_pk":"368441","name":"丸屋","kana":"まるや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県鎌ケ谷市鎌ケ谷四丁目17他","lat":35.75663056,"lng":140.01210278,"geo_status":"db","era":"明治30年頃／昭和31年改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積133㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0303","desc":"木下街道の鎌ケ谷宿に建つ、もと旅籠の建物。桁行五間、梁間七間の木造二階建、寄棟造桟瓦葺である。明治35年に廃業した後、間取りなどの改造を受けたが、柱や差物は木太く重厚な造りで、正面入口の揚戸構や庇など、宿場の面影を伝える旅籠建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013353"},{"id":"00013354","register_sub_id":"101","register_pk":"368442","name":"丸屋離れ","kana":"まるやはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県鎌ケ谷市鎌ケ谷四丁目17他","lat":35.75661111,"lng":140.01224444,"geo_status":"db","era":"明治30年頃／昭和50年代増築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0304","desc":"旧旅籠の東に建つ離れ。桁行五間半、梁間三間、木造平屋建、寄棟造桟瓦葺で、北面を除く三方に縁を廻らし、正面東寄りに玄関を付す。八畳と一〇畳を並べ、両室に床棚を設ける。小規模ながら、良質の造作を多用する明治期の新座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013354"},{"id":"00006514","register_sub_id":"101","register_pk":"107497","name":"宮醤油店店舗","kana":"みやしょうゆてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26191906,"lng":139.885468,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0073","desc":"県道沿いに北面して建つ。桁行５間，梁間３間規模，木造２階建で，平入の切妻造，桟瓦葺。外観正面は１階に引戸，２階に格子窓を設ける。２階軒は出桁造で，桁隠に絵様繰形を施す。また１階には揚戸が残り現在も使用。堅牢で丁寧なつくりで，重厚な外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006514"},{"id":"00006515","register_sub_id":"101","register_pk":"107498","name":"宮醤油店店蔵","kana":"みやしょうゆてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.261929,"lng":139.885437,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0074","desc":"県道沿いに位置し，店舗の西方に連続して建つ。桁行３間，梁間２間半，土蔵造２階建で，平入の切妻造，桟瓦葺。小屋組は和小屋。外壁は下見板張とし，県道側に妻を見せ，庇を設けた塗戸を両開きに開く。店舗・脇蔵とともに重厚な外観で表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006515"},{"id":"00006518","register_sub_id":"101","register_pk":"107501","name":"宮醤油店脇蔵","kana":"みやしょうゆてんわきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26193585,"lng":139.88557276,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0075","desc":"県道沿いに位置し，店舗の東方に建つ。桁行５間，梁間２間半，土蔵造２階建で，平入の切妻造，桟瓦葺。小屋組はトラスの形式をとる。外壁は下見板張とし，県道側に妻を見せて１・２階に片開塗戸を開く。店舗・店蔵とともに重厚な外観で表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006518"},{"id":"00008650","register_sub_id":"101","register_pk":"149371","name":"ヤマニ綱島商店店舗","kana":"やまにつなしましょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県木更津市中央2-1412-1","lat":35.38372825,"lng":139.92121694,"geo_status":"db","era":"江戸末期／大正後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積100㎡","structure_material":"木造平屋一部2階建","registered":"2011.07.25(平成23.07.25)","register_no":"12 － 0153","desc":"通りに西面して建つ。切妻造桟瓦葺の大壁造の2棟を前後に並べ、正面と南側面に下屋を付け、正面に銅板葺庇を通す。正面は開放し、側面は漆喰の土蔵風に仕上げる。内部は前店蔵を店舗、中店蔵を仕事場とする。棟高の異なる蔵造が前後に並ぶ独特の外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008650"},{"id":"00003393","register_sub_id":"101","register_pk":"104383","name":"旅館松の家","kana":"りょかんまつのいえ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県勝浦市勝浦30","lat":35.14819062,"lng":140.31598217,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺一部銅板葺、建築面積415㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0055","desc":"旧市役所通りに北面して建つ木造２階建の和風旅館。通り沿いの主体部は，桁行８間規模の入母屋造，桟瓦葺で，２階はたちが高く，木造和風旅館特有の開放的なつくりになる。正面１階中央の玄関上部に唐破風を付けて旅館建築らしさを演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003393"},{"id":"00003527","register_sub_id":"101","register_pk":"104517","name":"伊勢五蔵","kana":"いせごくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都文京区千石三丁目38-9","lat":35.7269108,"lng":139.74030214,"geo_status":"db","era":"明治前期／昭和3改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0158","desc":"主屋の北に隣接する道具蔵。２階建，土蔵造，切妻造，桟瓦葺で，通りに面した主屋精米所奥に表に妻面を見せて建つ。外壁はモルタル塗で石造風に目地を切り，軒蛇腹，腰部に水切りを付ける。立ちの高い重厚な外観は，主屋と並んで独特の商家の構えを造り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003527"},{"id":"00003526","register_sub_id":"101","register_pk":"104516","name":"伊勢五主屋","kana":"いせごしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都文京区千石三丁目38-9","lat":35.72685996,"lng":139.74036169,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積124㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0157","desc":"江戸時代から続く米屋。主体部は２階建，切妻造，桟瓦葺で，南に寄棟造の平屋部が接続する。１階は通りに面し帳場を取り，６畳，８畳，４畳半などの各室を配し，２階は表側を座敷，裏は物置とする。軒の低い佇まいや格子窓など，往時の町家の姿をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003526"},{"id":"00008263","register_sub_id":"101","register_pk":"133905","name":"伊勢屋店舗兼主屋","kana":"いせやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区日本堤1-208","lat":35.72508934,"lng":139.79708798,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積44㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0262","desc":"土手通りに西面して店を開き、東と南も街路に面する。間口４．６ｍ奥行１０ｍの木造２階建、入母屋造妻入桟瓦葺。外壁は下見板張、軒下と妻面は漆喰仕上げとする。１階を店舗、２階を住居とする。正面のカウンターなど、往時の天麩羅屋の佇まいを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008263"}];
